(window.STORIES=window.STORIES||[]).push(...[{"n": 33, "l": "الجزء ٤٧ | أصحاب السبت | وجزء ٤٨ | فتية الكهف", "u": "https://www.facebook.com/groups/710210019782034/permalink/755359691933733/", "t": "#قصص_الأنبياء\n#الحلقة_السابعة_والأربعون\n#أصحاب_السبت\nبما إننا اتكلمنا عن يأجوج ومأجوج والسد..وقلنا إننا نحط بيننا وبين الفتن سد،\nفأنسب قصة نتكلم عنها النهاردة هي قصة أصحاب السبت\nليه يعني\nخلونا نشوف السبب\nاليهود كانوا بيقولوا إنهم أحباب الله،\nفربنا قال لهم لو كلامكم صحيح ، طيب ليه بيعذبكم بذنوبكم وعصيانكم وجحودكم \nربنا مش بيعذب إللي بيحبه، ممكن يعاقب المؤمن عشان يفوق من غفلته ، لكن نزول العذاب من ربنا على ناس معينة مش بيكون وهو بيحبهم عز وجل..\n\"وَقَالَتِ الْيَهُودُ وَالنَّصَارَىٰ نَحْنُ أَبْنَاءُ اللَّهِ وَأَحِبَّاؤُهُ ۚ قُلْ فَلِمَ يُعَذِّبُكُم بِذُنُوبِكُم ۖ بَلْ أَنتُم بَشَرٌ مِّمَّنْ خَلَقَ\"\nأيوة ربنا فضّل بني إسرائيل بالنبوة والمُلك على باقي البشر في زمانهم، لكن إللي بيعصي وبيُعرِض عن البينات ويؤذي الرسل ويُبارز ربنا بعصيان أمره؛ ربنا بيعذبه في الدنيا قبل الآخرة.. \nعايزين مثال إن إللي بيفسق عن أمر ربه ويبارزه بالعصيان ده ربنا بيعذبه في الدنيا؟\nعندنا قصة أصحاب السَّبْت\nأصحاب السبت دول هم قوم من بني إسرائيل، منعرفش زمانهم كان إمتى بالتحديد، لكن يُقال إنهم كانوا في زمن داوود عليه السلام،\nوكانت قرية اليهود دي جنب البحر، فطبعا ده معناه إنهم كانوا بيعتمدوا على صيد السمك في غذائهم.\nربنا كان محرّم عليهم صيد السمك في يوم السبت... باقي الأسبوع مباح الصيد عادي، لكن يوم السبت لأ\n☆طيب اشمعنى يوم السبت\nكل نبي من الأنبياء بيقول لقومه على يوم الجمعة وفضله،\nفلما موسى عليه السلام قال لبني إسرائيل عن يوم الجمعة زي باقي الأنبياء؛\nبني إسرائيل اعترضوا وقالوا لأ السبت أحسن، وقعدوا يبرروا ويجادلوا، فربنا قال لهم خليكم في السبت.. \nفلما جاء زمن قرية أصحاب السبت ربنا ابتلاهم إنهم لا يصطادوا السمك يوم السبت، كاختبار وامتحان لهم على الطاعة\nفي البداية كانوا ملتزمين بعدم صيد السمك، وكانوا بيصطادوا في باقي أيام الأسبوع،\nلكن مكنش بيطلع لهم سمك في البحر غير يوم السبت\nطول الأسبوع مفيش ولا سمكة.. ويوم السبت السمك كثير جدا لدرجة إنه بينط على بعض وبيشوفوه بعنيهم\n☆زي مثلا لما الواحد بيبدأ يتبع أوامر ربنا ونواهيه، ويقول خلاص بس أنا تبت \nمثلا تبت من سماع الأغاني والمعازف والمسلسلات.. فبقى كل ما يمشي في مكان يسمع الأغاني إللي كان بيحبها وكان على طول بيسمعها، وكإن الشارع كله قرر فجأة يشغلها\nأو مثلا واحدة تابت من التبرج ولبست الحجاب الشرعي، تقوم طول ما هي ماشية عمالة تشوف البنات المتبرجة بعدد كبير وكإنهم مكنوش موجودين قبل كده\nهمّ كانوا موجودين، لكن لإنها بقت مختلفة عنهم فبقوا باينين جدا قصادها، وربنا بيختبرها بيهم،\nيعني دي تقول لها إنتِ كبّرتي نفسك ليه باللبس الغريب ده؟!  والتانية تقولها شكلك وحش كده، والتالتة تقول ...والعاشرة والعشرين....كل ده اختبار\nماهو ياجماعة سهل جدا إن الواحد يقول أنا مؤمن أو أنا ملتزم بأوامر ربنا.. الكلام سهل\nإزاي الإنسان يعرف إذا كان صادق فعلا في كلامه ولّا لأ؟\nبالإبتلاء والامتحانات ومُفترق الطرق وعند المشاكل والصعاب والفتن والشهوات....و...و .. و\nربنا يعلم الغيب أيوة، ويعلم إذا كان الشخص ده صادق ولّا لأ، بس مش بيحاسبنا عز وجل بسابق علمه فينا\nإنما بيحاسبنا باللي احنا بنعمله\nفبيبتلي الإنسان عشان يقوله شوف نفسك.. شوف أفعالك.. هل انت فعلا صادق في كلامك وايمانك والتزامك ولّا لأ\nفلو صبر الإنسان قصاد الفتن والمُغرِيات واستمر على طريق الإلتزام يبقى هو فعلا كان صادق، \nلكن لو رجع خالص زي الأول وأكثر يبقى مكنش صادق\n\"أَحَسِبَ النَّاسُ أَن يُتْرَكُوا أَن يَقُولُوا آمَنَّا وَهُمْ لَا يُفْتَنُونَ\"\nفربنا خلى السمك يطلع على وش المية يوم السبت بكميات كبيرة ويغوص في أعماق البحر باقي الأسبوع،\nوسبحان الله لو مكنوش جادلوا في يوم الجمعة، كان زمانهم بياكلوا السمك عادي يوم السبت\n☆وهنا ملحوظة مهمة:\nوهي إننا لما بنطمع في حاجة غير اللي ربنا إداهالنا، أحيانا بنكون بنتمنى الشر لأنفسنا واحنا مش عارفين.. \nربنا بيقول:\n\"وَيَدْعُ الْإِنسَانُ بِالشَّرِّ دُعَاءَهُ بِالْخَيْرِ ۖ وَكَانَ الْإِنسَانُ عَجُولًا\"، \nفدايما في أمور الدنيا نرضى بالمقسوم ونحمد ربنا عليه ونطمئن لاختيار ربنا لينا دايما،\nولو هنطلب شي دنيوي محدد نقول في الآخر: يارب لو فيه خير،\n لكن في أمور الآخرة والنجاة، ندعي براحتنا طبعا بدون قلق\nالمهم،\nبني إسرائيل كانوا صابرين على ابتلاء يوم السبت وثابتين على طاعة ربنا في عدم الصيد فيه،  لحد ما واحد منهم عمل إيه\nعمل حيلة ...\nحفر يوم الجمعة زي حفرة كبيرة جنب البحر، عشان لما الموج يجيب السمك يوم السبت، يدخل السمك في الحفرة، وميعرفش يطلع تاني، وييجي هو يوم الأحد ياخد السمك من الحفرة.. وبكده ما يبقاش اصطاد يوم السبت، وكإن ربنا مش مطلع على مكره وتحايله على الحرام\n\"وَاسْأَلْهُمْ عَنِ الْقَرْيَةِ الَّتِي كَانَتْ حَاضِرَةَ الْبَحْرِ إِذْ يَعْدُونَ فِي السَّبْتِ إِذْ تَأْتِيهِمْ حِيتَانُهُمْ يَوْمَ سَبْتِهِمْ شُرَّعًا وَيَوْمَ لَا يَسْبِتُونَ ۙ لَا تَأْتِيهِمْ ۚ كَذَٰلِكَ نَبْلُوهُم بِمَا كَانُوا يَفْسُقُونَ \"\n☆عارفين زي إيه \nرسول الله ﷺ  قال:\n\"لعن الله الواشمات والمُتَفَلّجات للحُسْن والمُتَنمّصات المُغَيّرات لخلق الله\"\nفعلة التحريم هي التغيير لخلق الله\nفتيجي واحدة تعمل إيه\n تقوم مشقرة حواجبها《 وترفّعها خااالص كأنها متنمصة بالضبط》...وتقول أنا مشلتش ولا شعراية أهه أنا شقرت بس\nطيب ماهي النتيجة في الحالة بتاعتنا دي واحدة...وهو التغيير لخلق الله..وده سبب التحريم أساسا\nطبعا أنا بتكلم في نقطة إللي بتشقر حواجبها وبتخليها زي إللي عاملة حواجبها بالضبط، \nوإلا فالتشقير عليه خلاف بين العلماء، فريق قال جائز وفريق قال محرم، عشان بس ميختلطش الأمر على الناس وحد يفهم كلامي خطأ\nالمهم،\nالراجل اليهودي ده استعمل وسيلة حلال، حيلة مشروعة مش حرام يعني، عشان يوصل لشيء محرم ربنا نهى عنه.. \n فبعد ما أخد السمكة، راح بيته وشواها، وانتم عارفين السمك المشوي ريحته بتبقى عاملة إزاي\nفجاره شم الريحة وجه يسأله انت جبت السمك منين وعملت إيه،\nحكى له إللي عمله، راح التاني عامل زيه،\nوالثالث والرابع لحد ما الموضوع انتشر في بني إسرائيل\n☆حاولوا تربطوا كده بواقع بني إسرائيل والواقع بتاعنا\nزمااان مكنش في واحدة تقدر تمشي كاشفة وشها حتى،\nلحد ما كشفت واحدة من النساء وشها والنساء بقت تقلدها وبقى اسمه تحرر،\nوبعد كده بدأت النساء تكشف حجابها نفسه ثم اللبس بدأ يبقى كاشف أكتر ما هو ساتر و شوية شوية لحد ما وصل بيهم الحال يلبسوا زي ما كلنا بنشوف في الشوارع  للأسف ولا حول ولا قوة إلا بالله..\nكذلك السجاير والحشيش وترك الصلاة و...و...\nكل ده بدأ بمجموعة صغيرة، وبعدين المجموعة كبرت، لحد مابقت ظاهرة في المجتمع،\nوعشان كده الإسلام حاطط الحدود والعقوبات الرادعة، عشان نقلل ونحجّم من انتشار وشيُوع الفتن بين الناس، \nلكن فين بقى تطبيق الإسلام في مجتماعتنا\nانقسم الناس في بني إسرائيل على ثلاثة أقسام:\n◇القسم الأول: قسم بدأ يصطاد السمك وياكل ويجاهر بالمعصية عادي خااالص وده كان أكبر قسم... وكإن لسان حالهم بيقول:\nإيه يا جماعة هو احنا بنعمل حاجة غلط...؟! هو انتم لا سمح الله شوفتونا اصطادنا يوم السبت؟ إيه التشدد بتاعكم ده\n◇والقسم الثاني: ناس بتؤمر بالمعروف وبطاعة الله، وتنهى عن المنكر وعصيان الله و التحايل على الحرام، \nيعني ناس بتقول للعصاة حرام كده، إنتم بتعصوا ربنا... إنتم بتحتالوا على شرع ربنا... إنتم كده بتستهزءوا بالله وآياته وبتستهينوا بوعيده... يا جماعة مينفعش .. ربنا بيمهل ولا يهمل... وهكذا.. \nوالتانيين؟؟ ولاااا همّ هنا\n◇والقسم الثالث بقى جماعتنا الساكتين\nحزب الكنبة زي ما بيقولوا في زماننا.. لكن في نوعين من الساكتين دول:\n1-إللي بيقولوا مالناش دعوة، كل واحد حر، خليني في نفسي... وياريتهم يسكتوا على كده\nلأ، ده كمان بيعترضوا على الناس إللي بتأمر بالمعروف وتنهى عن المنكر ويعاكسوا شغلهم، \nبيقولوا لهم باندهاش وسلبية: انتم بتنصحوهم ليه؟ \nماهمّ كده كده إللي في دماغهم في دماغهم، بتوجعوا دماغكم انتم ليه بقى! ما ربنا هو اللي هيحاسبهم! هو انتم إللي هتحاسبوهم؟! اهدوا كده وكبروا دماغكم!\n \"وَإِذْ قَالَتْ أُمَّةٌ مِّنْهُمْ لِمَ تَعِظُونَ قَوْمًا ۙ اللَّهُ مُهْلِكُهُمْ أَوْ مُعَذِّبُهُمْ عَذَابًا شَدِيدًا ۖ \"\nلكن النوع ده مع ذلك، من جواهم في قلبهم مش راضيين عن المنكر ده وعارفين إنه غلط\n2-والنوع التاني من الساكتين: ناس بيقولوا نفس كلام النوع الأول لكنهم في قلبهم راضيين بالمنكر ده ومش مقتنعين إنه غلط، ودول يدخلوا مع العصاة على طول\nطب كان رد الناس الناصحين إللي من القسم التاني إيه على إللي بيقولوا لهم كبروا دماغكم وسيبوهم براحتهم ماهو ربنا اللي هيحاسبهم؟\n\"قَالُوا مَعْذِرَةً إِلَىٰ رَبِّكُمْ وَلَعَلَّهُمْ يَتَّقُونَ\"\nيعني إحنا بننصح عشان نرفع العذر من علينا عند السؤال عن إنكار المنكر بين يدي الله عز وجل،\nوكمان يمكن النصيحة دي تؤثر فيهم في يوم من الأيام وربنا يجعلها سبب في هداتيهم كلهم أو بعضهم\n☆طيب قفزة كبيرة كده من عصر بني إسرائيل لعصرنا الحالي كده ونقارن بين حالهم وحالنا\nطبعا كلنا شايفين انتشار المعاصي في كل مكان ليل نهار في البيوت والشوارع وكل مكان\nيا ترى بقى كل واحد مننا في أنهي قسم من الأقسام الثلاثة؟\n◇هل يا ترى أنا من الناس إللي بتعصي أوامر ربنا وتتحايل على الحرام بل وبتجاهر بالمعصية بلا حياء ولا خجل من الناس..؟ \nهل تركت الأغاني وبقيت أسمع أناشيد بالإيقاع والمؤثرات الصوتية زي الأكابيلا والبيت بوكس وأقول ماهي إسلامية؟\n☆الأكابيلا والبيت بوكس دي عبارة عن أصوات تشبه الموسيقى بالضبط بتكون مصاحبة للأناشيد.\nهل أنا من الأخوات إللي بتطلع في فيديوهات بث مباشر يشوفها العالم كله رجال ونساء وكفار ومؤمنين وبَرّ وفاجر، وبتطلع تضحك وتهزر وتخضع بالقول وتتبرج بالزينة بحجة الدعوة إلى الله؟\n◇ولا أنا من القسم الثاني إللي بيصلح في نفسه أيوة، بس سايب الناس تعصي ربنا عادي وحتى وشه مش بيتغير لما يشوف حرمات الله إللي بيتم انتهاكها ليل نهار،\nبل معنديش مشكلة كمان أصاحب الشخص العاصي ده عادي وأخرج معاه وآكل وأشرب ومبنصحوش يبطل الحرام ولا بعتزله وهو بيعمله؟\n تلاقي الزوجة تقعد جنب زوجها وهو بيتفرج على الأفلام والمسلسلات عادي،\nتلاقي البنت لابسة الحجاب الشرعي وماشية في وسط الشارع ، مع بنت لابسة بنطلون مقطع ولبس متبرج،\nوماشين سوا بمبدأ مليش دعوة خليني في حالي.. أصل أنا لو اتكلمت الناس مش هتقبل مني... الناس هتصدني.. الناس هتكرهني وتبعد عني.. الناس... الناس... ولا حول ولا قوة إلا بالله\n◇ولّا أنا من القسم التالت إللي بيؤمر بالمعروف، وبنصح الناس وأفهمهم بالحكمة والموعظة الحسنة،  وبنهى عن المنكر بدون منكر أشد منه، وبعمل ده كله ثبات بحول الله وقوته، مهما حصل ومهما تعرضت للأذى\nلما بني إسرائيل استمروا في عصيانهم لله، الناس إللي كانوا بينصحوهم خافوا على نفسهم أحسن ينزل عليهم العذاب همّ كمان لما ينزل على العصاة دول،\nفراحوا بنوا 《سور》 بينهم وبين العصاة، وانعزلوا عنهم وبقى لكل مجموعة فيهم باب يخرجوا منه..\nوفي يوم من الأيام، لما الناصحين خرجوا من الباب بتاعهم، لقوا باب العصاة مقفول ومحدش خرج\nفقالوا لبعض أكيد حصل حاجة..!\n فراح واحد تسلق الجدار وبص عليهم لقاهم كلهم اتمسخوا قردة\n وخنازير\n\"فَلَمَّا عَتَوْا عَن مَّا نُهُوا عَنْهُ قُلْنَا لَهُمْ كُونُوا قِرَدَةً خَاسِئِينَ\"\n\"وَلَقَدْ عَلِمْتُمُ الَّذِينَ اعْتَدَوْا مِنكُمْ فِي السَّبْتِ فَقُلْنَا لَهُمْ كُونُوا قِرَدَةً خَاسِئِينَ\"\nوبعد كام يوم -يُقال ثلاثة أيام- مات العصاة إللي ربنا مسخهم دول، فهمّ ملهمش نسل خالص زي ما الناس فاكرة \nفربنا نجّى الناصحين بسلام، ودول الفريقين إللي القرآن حكى عنه في الآية:\n\"فَلَمَّا نَسُوا مَا ذُكِّرُوا بِهِ أَنجَيْنَا الَّذِينَ يَنْهَوْنَ عَنِ السُّوءِ وَأَخَذْنَا الَّذِينَ ظَلَمُوا بِعَذَابٍ بَئِيسٍ بِمَا كَانُوا يَفْسُقُونَ \"\nطب والناس إللي سكتت\n؟\nربنا مجبش سيرتهم بالتحديد هل همّ مع إللي العذاب أخذهم بظلمهم؟ ولّا همّ نجوا مع الناصحين إللي ربنا نجاهم؟\nعشان كده العلماء اختلفوا، قسم منهم قال هلكوا مع العصاة لأنهم متكلموش،\nوقسم تاني من العلماء قالوا نَجَوا من الهلاك عشان كانوا كارهين للمنكر بقلوبهم رغم سلبيتهم في إنكارهم،\nفمفيش حسم للمسألة دي والعلم عند الله، \nحتى بعض المشايخ كان بيقول عن الساكتين دول جملة فيها عبرة جميلة قال: ملهمش أي دور فملهمش أي ذِكر، كإنهم هوا ملوش وزن ولا أثر..\n☆طيب ليه ربنا بيقولنا على موضوع المسخ ده\nلأن هيكون في مسخ للناس قبل قيام الساعة \nقال رسول الله ﷺ: \n\"بين يدي الساعة مسخٌ وخَسف وقذف\"\nالمسخ يعني بشر يتقلبوا لصورة تانية غير بشرية، زي بني إسرائيل كده\nوالخسف يعني الأرض تنشق وتبلع ناس أو بيوت، زي خسف قارون كده لما حكينا قصته،\nوالقذف يعني ربنا يقذف حجارة من السماء على العصاة أو المُكذبين، زي ما حكينا في اللي حصل لقوم لوط\n◇طيب مين الناس إللي هيحصل فيهم كده\nهيحصل المسخ والخسف والقذف في نوعين من الناس:\nالنوع الأول:\n◇الناس إللي بيتكلموا في القَدَر، ويقولوا ربنا ماقدّرش أي حاجة، ومبيعرفش الأمور إلا بعد ما بتحصل وتقع! وإن الناس همّ إللي بيخلقوا الأفعال مش ربنا إللي خقلها\nودول طائفة من ضُلّال العقيدة، اسمها طائفة \"القدرية\"\n◇والنوع الثاني: همّ أصحاب الخمور والأغاني\nوده ظاهر ومنتشر جدا حوالينا\nلما رسول الله ﷺ قال\"في هذه الأمة مسخ وخسف وقذف\" واحد من الصحابة سأله إمتى الكلام ده\n؟\nفرسول الله ﷺ قال له: \"إذا ظهرت القِينات، والمعازف\"\nالقينات يعني المغنيات والمعازف يعني أي حاجة بتطلع موسيقى،\nوده من أكبر الأدلة إللي بيستند إليها العلماء في تحريم الموسيقى\nلأن ربنا مش هيمسخ البشر عشان بيعملوا حاجة حلال أكيد يعني، ولّا عشان حاجة من الصغائر حتى\nوانتم أكيد شافين كمية انتشار الموسيقى والأغاني عامل إزاي ولا كإنه بقى ورد يومي زي أوراد الأذكار كده في الفيسبوك واليوتيوب والشوارع والأخبار والألعاب الاكترونية وحتى اللعب إللي مش إلكترونية حتى لو مجرد عربية بالريموت لازم تلاقي حاشرين معاها موسيقى،\nوفي المواصلات والمطاعم والنوادي والبيوت وحفلات الزفاف والولادة وغيره.. في كل مكان حرفيا\nوالمشكلة الأكبر إن بعض الملتزمين لجؤوا لما يُسَمَّى بالبديل الإسلامي، \nأناشيد إسلامية لكن بإيقاع وموسيقى! الموسيقى حرام والإيقاع حرام، سواء كان مع نشيد إسلامي أو أغنية فسق وفجور..\nبس مين بيبحث عن الحلال والحرام زي ما بيبحث كده عن الأكل والشرب؟\nدة معرفة الحلال والحرام أهم والله من الأكل والشرب، لإن بيهم بتكون حياتنا الأبدية..\n¤طيب والحل\nفي الأمر بالمعروف والنهي عن المنكر\nتخيل كده لما تعدي على محل مشغل أغاني وحطيت إيدك على ودنك والناس شايفاك\nانت كده أمرت بالمعروف ونهيت عن المنكر بأقل وسيلة من غير ما تتكلم، \nوكمان قلدت النبي ﷺ في الحركة دي لما سد ودانه عن المعازف لما عدت جنب منه\nوشوف كم إنسان ممكن يلفت نظره تصرفك ده فيسألك فتحكيله فعل النبي ﷺ فيتأثر ويقلدك؟\nميهمكش استهزاء إللي هيستهزأ.. إنت بترضي ربنا عز وجل مش بترضي الناس..\nتخيل لو ركبت مواصلة ولقيت السواق مشغل أغاني فقلت له: لو سمحت... أنا ممكن أموت في أي لحظة دلوقتي، فأنا مش عايز أموت وأنا آخر حاجة كنت بسمعها هي الأغاني\n، فياريت تقفلها .\nإنت هنا ذكّرت نفسك وذكّرت السواق بالموت ووعظته موعظة بليغة،\nولعله يتوب بسبب كلمتك لإن مفيش حد يتمنى يموت وهو بيسمع أغاني\nبعكس لو جيت قولت له: يا أستاذ الأغاني حرام اطفيها\n هيقولك مش عاجبك انزل.. ومش بعيد يشتمك \nفنجتهد في نصح الناس بالحكمة والموعظة الحسنة والمدخل المناسب لكل شخص وكل موقف، وسددوا وقاربوا وأبشروا\n◇طيب نصحنا الناس بالحُسنى وبرده الناس مصممين وإللي في دماغهم في دماغهم نعمل إيه\nشوفتوا لما الناس إللي كانوا بينصحوا بني إسرائيل عملو إيه لما بني إسرائيل مستجابوش\nبنوا السور واعتزلوا العصاة عشان خافوا على نفسهم من عذاب ربنا\nفزي ما قلنا المرة إللي فاتت في قصة يأجوج ومأجوج:\nحط سد بينك وبين الفتن، أهه النهاردة بنقول حط حائط وسور بينك وبين الناس اللي مصممة إنها تجهر بمعصية الله\nانت نصحت وكررت كتير، وهمّ رافضين، يبقى وجودك معاهم ممكن يبقى فتنة ليك بالفعل مع الوقت،\nوممكن الناس تفهم كمان بوجودك ده إنه تأييد للعصاة المجاهرين المعاندين، في أفعالهم.. \n¤يعني ننعزل عن الناس\n.. بس الإسلام ماقلش ننعزل..! طب ومصالحا وحياتنا و...و...\n!\nواحنا مقلناش ننعزل لإن غصب عننا هنتعامل وهنختلط بالناس، لكن نختلط بالناس واحنا بننكر المنكر ونؤمر بالمعروف، \nو لو مكنش في استجابة من الناس نصبر ممكن ربنا يهديهم في يوم من الأيام،\nممكن مثلا لما أنا أقول كلمة وتؤثر تأثير بسيط في إنسان حد تاني ييجي ينصح نفس الشخص فيكتمل التأثير وربنا يهديه،\n لكن لو خوفنا على نفسنا من الفتنة، نبعد عنهم ونكمل دعوة عامة للناس ونوصل لهم صوتنا من بعيد،\nلكن لو هنختلط بيهم واحنا موقفين إنكار منكر، هنا الخطر الحقيقي\n◇طيب لو مش عارفين  نعمل كده\nيبقى أنكر المنكر بقلبي\nلأن إنكار المنكر بالقلب محدش له حجة إنه ميعملوش وهو واجب على كل مسلم وإنكار المنكر بالقلب بإننا نزول عنه\nيعني مثلا متبقاش واحدة رايحة فرح كله موسيقى ورقص ورجالة مع ستات وتقعد في وسط الناس وتتصور مع العروسة وتقول أنا منكرة المنكر بقلبي\nلا يا حبيبتي إنتِ كده شاركتي في الذنوب دي كلها...لأنك قعدتي بمزاجك ورغبتك وانتِ تقدري متروحيش من الأساس\nفلازم يكون في توازن ...لو في منكر أُنكره بإيدي أو لساني لو المنكر متغيرش يبقى أسيبه وأمشي وهو ده إنكار القلب\n¤طيب هو الأمر بالمعروف والنهي عن المنكر حاجة مهمة يعني\nترك الأمر بالمعروف والنهي عن المنكر سبب في نزول البلاء وكمان عدم إستجابة الدعاء\nفكروا في الواقع بتاعنا كده وشوفوا الحديثين دول\nقال رسول الله ﷺ :\n\" وَالَّذِي نَفْسِي بِيَدِهِ لَتَأْمُرُنَّ بِالْمَعْرُوفِ، وَلَتَنْهَوُنَّ عَنِ الْمُنْكَرِ، \nأَوْ لَيُوشِكَنَّ اللَّهُ أَنْ يَبْعَثَ عَلَيْكُمْ عِقَابًا مِنْهُ، ثُمَّ تَدْعُونَهُ فَلَا\n يُسْتَجَابُ لَكُمْ\"\nوفي حديث تاني يقول:\nيَا أَيُّهَا النَّاسُ إِنَّ اللَّهَ عَزَّ وَجَلَّ يَقُولُ: \n\"مُرُوا بِالْمَعْرَوفِ وْانْهَوْا عَنِ الْمُنْكَرِ مِنْ قَبْلَ أَنْ تَدْعُونِي فَلَا أُجِيبُكُمْ،\n وَتَسْأَلُونِي فَلَا أُعْطِيكُم وَتَسْتَنْصِرُونِي فَلَا أَنْصُرُكُمْ\"\nطيب ماهو ممكن الأمر بالمعروف والنهي عن المنكر يعرضنا للأذى ..نعمل إيه\nده إللي هنعرفه الجزء الجاي إن شاء الله مع أصحاب الكهف\n#قصص_الأنبياء\n#الحلقة_الثامنة_والأربعون\n#فتية_الكهف\nاتكلمنا المرة إللي فاتت عن أصحاب السبت وأنواع الناس في الأمر بالمعروف والنهي عن المنكر،\nواتكلمنا عن أهمية الأمر بالمعروف والنهي عن المنكر وإن إللي ربنا بينجيه من المَهَالك العامة هو إللي بيأمر بالمعروف وينهى عن المنكر\nطيب لو الإنسان هيتعرض لأذى شديد جدا لو أمر بالمعروف ونهى عن المنكر يعمل إيه\nهنعرف الإجابة إن شاء الله من قصة فتية الكهف \nكان في مدينة قومها بيعبدوا الأصنام من دون الله، وبيقدموا القرابين للأصنام دي زي ما كان قوم إبراهيم عليه السلام بيعملوا لو تفتكروا،\nوكان الملك والأمراء من أوائل الناس إللي بتقدم القرابين للأصنام دي،\nفي وسط الكفر ده كان في شاب من أبناء الأمراء بيفكر مع نفسه كده: \nإزاي نسجد ونبكي ونتضرع ونُوهب قربان لصنم لا بيتكلم ولا بيسمع ولا حتى بيشاور أو بيتحرك..! \nأكيد في إله تاني للكون ده هو إللي خلقه وهو إللي يستحق العبادة\nطبعا الكلام ده كان جواه مش قادر يقول الكلام ده للناس حواليه لإنه عارف إنه لو اتكلم هيتعرّض لأذى شديد\nفي يوم عيد لهم والكل خارج عشان يقدم القرابين للأصنام ، الشاب ده اعتذر وقال إنه مش هيقدر يخرج معاهم،\nوبعدين راح ناحية شجرة لوحده عشان يفكر في حاله وحال قومه وهيعمل إيه بعد كده..\nوهو ماشي رايح يقعد في المكان ده لوحده لقى ستة من الشباب جايين معاه في نفس الوقت عند المكان ده \nفالشباب بصوا لبعض واستغربوا\nوكأن لسان حال كل واحد منهم بيقول:\nالمفروض إن النهاردة يوم عيد! والكل خرج عشان يقدموا القرابين...! الشباب دول بيعملوا إيه هنا..! يا ترى إيه إللي جابهم هنا\nفبدأوا يكلموا بعض ويسألوا إنت جيت هنا ليه.. وإنت .. وإنت... \nفكل واحد بدأ يتكلم عن إللي جواه واتضح إن كلهم بيفكروا نفس تفكير صاحبنا الشاب إللي اتكلمنا عنه من شوية\nفالشباب اتشجعوا واستقوُوا ببعض وقالوا :\nاحنا ربنا هدانا للإيمان بيه وبوجوده.. فمش هينفع نسكت.. لازم نعرَّف الناس إن إللي بيعملوه ده غلط، وإن الإله الحق هو الله خالق السموات والأرض، مش الأصنام إللي لا بتنفع ولا بتضر\nشباب مؤمن بربه وعنده همة عالية كمان في تبليغ الدين رغم خطورة الموقف.. عشان كده ربنا قال عنهم:\n\"إِنَّهُمْ فِتْيَةٌ آمَنُوا بِرَبِّهِمْ وَزِدْنَاهُمْ هُدًى\"\nهنا الشباب زي ما شفنا آمنوا بالله... واحنا عندنا القاعدة بتقول إييييه\nإن مادام فيه إيمان يبقى في إبتلاء وفتنة واختبار وتمحيص\n\"أَحَسِبَ النَّاسُ أَن يُتْرَكُوا أَن يَقُولُوا آمَنَّا وَهُمْ لَا يُفْتَنُونَ\"\nفإيه اللي حصل....؟ \nالملك عرف إن في مجموعة من الشباب مبتعبدش الأصنام مع باقي الناس، وبيقولوا إنهم بيعبدوا إله تاني،\nودول مش أي شباب على فكرة، دول كانوا أبناء الملوك والأمراء و الملك ده نفسه عارفهم شخصيا ..\nطبعا الشباب بقوا خايفين أكتر، لإنهم دلوقتي بقوا في مواجهة دولة كاملة.. \nيعني مش بس هيواجهوا أهلهم وأصحابهم، لأ دول هيواجهوا الشعب كله وهيواجهوا كمان الحاكم ذات نفسه.. الرئيس بجنوده وسلطانه.... وهمّ مجرد سبعة  أشخاص بس\n☆خليني أقرب الصورة أكثر\nشوفوا لما تكون واحدة عايزة تلبس نقاب مثلا أو عايزة تلتزم إلتزام صح بدينها ،\nوتيجي تكلم أهلها وهي عارفة إنهم ضد فكرة الإلتزام جُملة وتفصيلا..بتبقي عاملة إزاي..بتبقي بتفكري في إيه..قلبها بيكون خايف أد إيه\nودول أهلها من لحمها ودمها..بيخافوا عليها وبيتمنوا لها الخير أكثر من أي حد\nتخيلوا معايا الموقف، الملك خلاص استدعاهم...داخلين عليه القصر.. جنود في كل حتة.. والناس بتبص عليهم وتبدأ الوشوشة بينهم وبين بعض: \nيا ترى إيه إللي جمّع الشباب دول مع بعض...! وإيه إللي جابهم هنا في القصر...! ويا ترى الملك هيعمل فيهم إيه..؟! \nتساؤلات وهمسات وجلبة ودوشة، والشباب سامعين وشايفين كل ده، \nومع ذلك متقدمين بثبات عشان يقابلوا الملك.\nالملك شافهم داخلين... أنظار الوزراء والحاشية كلها عليهم.. مستنيينهم يتكلموا .. أول مرة يحصل موقف زي كده وحد يواجه الملك\nموقف يحبس الأنفاس فعلا...فتخيلوا موقف الشباب دول كان عامل إيه، وقلوبهم في الوقت ده كانت عاملة إزاي\nلإن هنا الإختبار والفتنة ، هل هيصبروا ويثبتوا على الإيمان،  ولّا هينكروا كل شيء ويسجدوا لصنم عشان الملك يصدقهم؟\nلكن الشباب كانوا واخدين القرار إنهم هيجهروا بالحق ويبينوا للناس إنهم يسيبوا عبادة الأصنام ويعبدوا الله الواحد الأحد، قرروا يعملوا كده رغم الصعاب إللي ممكن يواجهوها..\nبرغم الأذى إللي ممكن يتعرضوا له....\nومع ذلك مقالوش احنا نخلينا في نفسنا احنا معذورين، وهنعبد ربنا في السر بقى وأهه نعيش مع أهلنا في القصور مضطرين عشان محدش يشك فينا،\nما حنا بردو مش هننعزل يعني عن الناس ونسيب حياتنا \nوبالمناسبة\nالشباب دول قرروا يعملوا كده من نفسهم لله، يعني همّ مجلهمش وحي، ولا جالهم رسالة من ربنا بالأمر بالمعروف والنهي عن المنكر،\nلكن إحساسهم الفطري إنهم لازم يدعوا الناس لعبادة الله وإن ربنا هو المستحق للعبادة هو إللي خلاهم يقفوا الموقف ده ويعلنوا الحق للناس\nدي الأحداث إللي كانت بتحصل في الأرض،\nأما في السماء، فكان لربنا شأن تاني مع الشباب دول\nربنا عالم بكل شيء بيحصل وعالم بقلوب الشباب والخوف والفزع إللي فيها... \nوعالم بثباتهم وصدق لجوئِهم له وحده سبحانه.. تعتقدوا إن ربنا ممكن يسيب إنسان بيعمل حاجة لله ولله فقط وبصدق كده، ويكون المحرك لكل أعماله هو الرغبة في رضا الله ونشر دينه؟\nطبعا لأ... وحاشاه عز وجل.. \nلما الشباب ثبتوا وصَدَقُوا، ربنا كافئهم وأيّدهم..\nأول حاجة ربنا عملها مع الشباب دول كانت إنه ربط على قلوبهم..\nثبتهم.. طمّن قلوبهم.. مفيش خوف خلاص.. في قوة وصمود\nمبقاش هاممهم حد..بيتكلموا بكل جرأة وشجاعة:\nإحنا آمنا بالله ربنا إللي خلق السماوات والأرض، مش هنعبد ولا ندعوا غيره.. ولو عبدنا غيره يبقى احنا بنفتري الكذب على الله\nقومنا بيعبدوا أصنام لا تضر ولا تنفع، ومش معاهم أي بينة ولا دليل من ربنا على إن عبادة الأصنام دي صحيحة\nوأظلم الناس همّ إللي بيدّعوا ويزعموا على ربنا حاجة بالكذب وهو مقلش عليها ..\n\"وَرَبَطْنَا عَلَى قُلُوبِهِمْ إِذْ قَامُوا فَقَالُوا رَبُّنَا رَبُّ السَّمَاوَاتِ وَالْأَرْضِ لَنْ نَدْعُوَ مِنْ دُونِهِ إِلَهًا لَقَدْ قُلْنَا إِذًا شَطَطًا \"\nإيه اللي حصل\nطبعا أهل الباطل لغتهم الوحيدة إللي يعرفوها هي التهديد والتعذيب والقتل والبطش، ودي سُنّة كونية معروفة خلاص\nفالملك أمر جنوده إنهم يمسكوا الفتية دول وينزعوا ملابسهم لأنهم كانوا لابسين ملابس الأمراء،\nويلبسوهم ملابس عادية ويحبسوهم يمكن يرجعوا في كلامهم\nعارفين الملك عمل كده ليه\nالشباب زي ما قلنا دول أبناء أمراء، يعني بيسكنوا في أحسن القصور وبياكلوا أحسن الأطعمة، وبيلبسوا أحسن الثياب، ده غير الخدم والنعيم والمتع والنفوذ والمال..و..و..و... يعني عندهم مُلك الدنيا بين إيديهم\nفالملك تخيّل إنه لما يهددهم بإنه ياخد منهم مُلك الدنيا ده، إنهم ممكن يفكروا ويراجعوا أنفسهم تاني ويعيدوا حساباتهم\nلكن الملك ده، وفرعون كمان من قبله، وكل ظالم جبار قبلهم وبعدهم، مش فاهمين نقطة مهمة أوي،\nوهي إن الإيمان لما يستقر في القلب فعلا مش هيفرق مع الإنسان أي شيء من متاع الدنيا الزائل، \nلا هيفرق معاه ألم ترك المتع دي كلها، ولا حتى يفرق معاه أي ألم.. ولا في مُلك ولا مال ولا تعذيب ولا..ولا.. هيخلوه ساعتها يغير من عقيدته..\nلإن إللي بيوضح عنده البصيرة بالحق خلاص، مش بيبقى شايف قدامه ساعتها إلا رضا الله وبس\nالشباب عرفوا يهربوا من الملك.. محاولوش يتسعيدوا أي شيء من حقوقهم ومكانتهم دي.. تركوا القصور وتركوا الأموال والحياة إللي يتمناها أي إنسان عايز يعيش مرتاح ومتنعم في الدنيا.. \nطيب راحوا فين بعد كده؟ \nهل ربنا عوضهم بقصر أحسن من القصر إللي كانوا فيه؟\nهل ربنا عوضهم بأموال أكثر من الأموال إللي كانت عندهم؟ هل همّ نفسهم اشترطوا وقالوا يارب احنا هنسيب عبادة الأصنام وهنعبدك إنت، فلازم تعوضنا بقى،\nمش انت يارب قلت من ترك شيئا لله عوضه الله خيرا منه ؟\nولا حاجة من دي حصلت... \nعارفين الشباب دول بعد ما كانوا عايشين في القصور مُنعمين على أحسن الفُرُش وبياكلوا أحسن أكل راحوا فين؟\nراحوا كهف \nكهف في الجبال وسط الصخور، كهف يعني ممكن يكون جواه حشرات وأفاعي وعقارب ومكان ضلمة..ممكن يكون جواه حيوانات مفترسة، مش بس كده ده مفيش حاجة يناموا عليها في الأرض غير التراب والحصى،\nوكل ده ليه\nإيه إللي يخليهم يستحملوا ده كله ويتخلوا عن حياتهم المريحة... إيه الدافع للهم ده\nالدافع هو البحث عن رضا الله \n . \n\"إِذْ أَوَى الْفِتْيَةُ إِلَى الْكَهْفِ فَقَالُوا رَبَّنَا آتِنَا مِنْ لَدُنْكَ رَحْمَةً وَهَيِّئْ لَنَا مِنْ أَمْرِنَا رَشَدًا\"\nوتخيلوا أول حاجة عملوها لما دخلوا الكهف الموحش ده كانت إيه؟\nأثبتوا عبوديتهم واعتصامهم بالله وحده أكتر وأكتر، وأظهروا افتقارهم له، ودعوه لإرشادهم وإنقاذهم من الكفار، \n\"إِذْ أَوَى الْفِتْيَةُ إِلَى الْكَهْفِ فَقَالُوا رَبَّنَا آتِنَا مِنْ لَدُنْكَ رَحْمَةً وَهَيِّئْ لَنَا مِنْ أَمْرِنَا رَشَدًا\"\nعملوا إللي عليهم ودَعوا... وربنا يُصَرَّف أمورهم بإللي يراه مناسب لهم.. يعني هما مُسلّمين أمرهم تمااااما لله\n\"وَإِذِ اعْتَزَلْتُمُوهُمْ وَمَا يَعْبُدُونَ إِلَّا اللَّهَ فَأْوُوا إِلَى الْكَهْفِ يَنْشُرْ لَكُمْ رَبُّكُمْ مِنْ رَحْمَتِهِ وَيُهَيِّئْ لَكُمْ مِنْ أَمْرِكُمْ مِرْفَقًا\"\nتعتقدوا ربنا يترك إنسان ضحّى من أجله سبحانه وعرَّض نفسه للأذى عشان بيدافع عن دين رب العالمين \nطيب ربنا عمل إيه مع فتية الكهف\nهل أنزل من السماء صاعقة على القوم الكافرين؟\nهل ربنا خسف بالكفار الأرض؟\n لأ... ولا أي حاجة من دي..\nربنا خلاهم يناموا\n\"فَضَرَبْنَا عَلَى آذَانِهِمْ فِي الْكَهْفِ سِنِينَ عَدَدًا \"\n☆نعم\nيعني الشباب طلبوا من ربنا النصر والرحمة فكانت الاستجابة إنهم يناموا \nآه والله.. ومش أي نوم ده هيناموا أكثر من ثلاثمائة سنة، ودي حكمة ربنا  عزو وجل إللي عمرنا ما هنحيط بها علما\nلكن خلونا نشوف كده جانب بسيط من الحكمة دي.. \nعارفين يعني إيه النوم في موقف زي ده؟ \n كإن ربنا بيوصل لنا رسالة إن مش دايما الانتصار بيكون في استخدام القوة والبطش والإهلاك والقضاء على الخصم.. ممكن يكون انتصارك على خصمك عن طريق إنه يخليك متحسش بيه خالص ، ويكون هو إللي حارق نفسه من الغيظ والغضب والتعب بسببك \nربنا جعل فتية الكهف يناموا مطمئنين بالهم مرتاح بعد قلق وخوف، \nوفي نفس الوقت ده كان الملك وجنوده بيبحثوا عنهم بين الجبال .. في الأودية.. في الكهوف.. \nفي كل مكان وبكل وسيلة ممكنة.. ضيعوا فلوسهم ووقتهم وطاقتهم وراحة بالهم وأعصابهم أيام وأيام.. ده غير الإحباط والفشل ..\nمين إللي تعب هنا وكان في كرب؟\nمين إللي انشغل وبذل أغلى ما يملك وبرده ما أخدش إللي هو عاوزه وعايش مكروب مهموم البال، ومين إللي نايم مرتاح مطمئن في حفظ الله ورعايته\nكإن ربنا بيقول لهم:\nناموا مطمئنين.. ومش بس هتناموا يوم ولا اتنين ولا شهر ولا شهرين..إنتم هتناموا ٣٠٩ سنة،\nومش بس كده .. لأ ده انتوا هتكونوا في حفظي ورعايتي بشكل كامل حتى إن الشمس إللي برة الكهف دي هسخرهالكم بشكل معين بحيث تديكم الفايدة بتاعتها تامة،\nوفي نفس الوقت ما تضروكوش ولا تؤذيكم بأشعتها وسخونتها،\n\"وَتَرَى الشَّمْسَ إِذَا طَلَعَتْ تَزَاوَرُ عَنْ كَهْفِهِمْ ذَاتَ الْيَمِينِ وَإِذَا غَرَبَتْ تَقْرِضُهُمْ ذَاتَ الشِّمَالِ وَهُمْ فِي فَجْوَةٍ مِنْهُ\"\nومش بس كده ده أنا هقلبكم على الجوانب اليمين والشمال كل شوية عشان الأرض ماتاكلش أجسادكم،\nوعشان جسمكم ميجيش فيه قُرح -إللي هي معروفة في زماننا باسم \"قُرَح الفِراش\"و إللي بتيجي للناس المرضى لمدة طويلة مش بيتقلبوا في السرير،\n\"وَنُقَلِّبُهُمْ ذَاتَ الْيَمِينِ وَذَاتَ الشِّمَالِ وَكَلْبُهُمْ بَاسِطٌ ذِرَاعَيْهِ بِالْوَصِيدِ\"\nيعني الكلب بتاعهم مادد دراعاته عند مدخل الكهف..\nفيا أهل الكهف، انتم وظيفتكم دلوقتي إنكم تناموا؛ لأن نصركم في النوم، مش هتقدروا تواجهوهم، لإن مش كل نصر ييجي بالمواجهة المباشرة في ساعتها\n \nزي ما ربنا نصر نوح عليه السلام بإنه أغرق الكفار، ونصر لوط بإنه قلب قريته زي ما قلنا قبل كده، نصر فتية الكهف بالنوم\nوما يعلم  جنود ربك إلا هو\nنام الفتية ٣٠٩ سنة ، وكان معاهم كلب  بيحرسهم،\nاحنا منعرفش الكلب جه منين، لكن ربنا ذكر لنا الكلب عشان يقول لنا حاجة مهمة،\nوهي إننا نصاحب الصالحلين ؛مصاحبة الصالحين بتجلب الشرف والتكريم من الله عز وجل..\nفذِكر الكلب بالذات بيعلمنا إن مهما كان شأنك وضيع وملكش قيمة، فذِكرك هيكون مُشرِّف وهتتكرم لو إنت كنت مصاحب الأخيار المؤمنين،\nفالكلب على الرغم من نجاسته، لكن ربنا ذكره لمجرد إنه كان مصاحب الصالحين، فما بالنا بالصالحين نفسهم\n \nزي ما الإمام الشافعي كان بيقول:\nأحب الصالحين ولست منهم، عسى أن أنال بهم شفاعة.. فصحبتهم بتكون من أسباب تكريم الله للإنسان.. \nفاللهم ارزقنا صحبة الصالحين واجعلنا منهم\nالفتية بقى لما ناموا كانوا نايمين وعينهم مفتوحة وبتنظر ناحية باب الكهف، حتى الكلب كمان كان بنفس المنظر!\n\"وَتَحْسَبُهُمْ أَيْقَاظًا وَهُمْ رُقُودٌ\" \nفلو حد شافهم بالشكل ده كان هيتفزع جدا من منظرهم وهيطلع يجري ده لو مامتش بالسكتة القلبية يعني\n\"لَوِ اطَّلَعْتَ عَلَيْهِمْ لَوَلَّيْتَ مِنْهُمْ فِرَارًا وَلَمُلِئْتَ مِنْهُمْ رُعْبًا\"..\nوعدت السنين.. وصحيوا..\nلما صحيوا من النوم شكلهم كان زي ماهو ما اتغيرش، لا شعرهم طِوِل ولا ضوافرهم طولت ولا أي حاجة خالص\n☆إيه ده ..إزاي يعني يقعدوا السنين دي كلها وشعرهم مايطولش وشكلهم مايتغيرش\nيعني إللي كان قادر يخليهم يناموا أكثر من ثلاثمائة سنة بدون أي أذى عضوي أو غيره، مش قادر يجعل أشكالهم ماتتغيرش\nأول ما صحيوا، سألوا بعض هو احنا نمنا أد إيه\nفواحد منهم قال ممكن يوم.. أو ممكن كام ساعة، لما شافوا الشمس قربت على الغروب،\nوهمّ كانوا داخلين الكهف في أول النهار، فلما لقوا نفسهم مش متأكدين قالوا الله أعلم إحنا نمنا أد إيه\n\"وَكَذَلِكَ بَعَثْنَاهُمْ لِيَتَسَاءَلُوا بَيْنَهُمْ قَالَ قَائِلٌ مِنْهُمْ كَمْ لَبِثْتُمْ قَالُوا لَبِثْنَا يَوْمًا أَوْ بَعْضَ يَوْمٍ قَالُوا رَبُّكُمْ أَعْلَمُ بِمَا لَبِثْتُمْ \"\nوبعدين انتبهوا إنهم جاعوا وعايزين ياكلوا، لكن هيجيبوا أكل إزاي دلوقتي وهم مطلوبين\nفاتفقوا إن واحد منهم يروح يشتري أكل بالنقود إللي معاهم، لكن يتخفّى كده ومايخليش حد ياخد باله منه،\n\"فَابْعَثُوا أَحَدَكُمْ بِوَرِقِكُمْ هَذِهِ إِلَى الْمَدِينَةِ فَلْيَنْظُرْ أَيُّهَا أَزْكَى طَعَامًا فَلْيَأْتِكُمْ بِرِزْقٍ مِنْهُ وَلْيَتَلَطَّفْ وَلَا يُشْعِرَنَّ بِكُمْ أَحَدًا \"\nلأنهم لو عرفوا مكاننا هيقتلونا بأبشع طريقة وهي الرجم، أو يجبرونا إننا نعبد الأصنام وساعتها يبقى احنا ضعنا\n\"إِنَّهُمْ إِنْ يَظْهَرُوا عَلَيْكُمْ يَرْجُمُوكُمْ أَوْ يُعِيدُوكُمْ فِي مِلَّتِهِمْ وَلَنْ تُفْلِحُوا إِذًا أَبَدًا \"\n☆القتل في وجهة نظرهم مش مشكلة لإن كده كده الكل هيموت، \nلكن المشكلة لو أجبروهم بالتعذيب على المعصية والرجوع للكفر مرة ثانية فهيخسروا الدنيا والآخرة\nفشاب منهم خرج من الكهف، ومشي في الطريق .. عمال يبص يمين وشمال! الطريق مختلف والناس شكلهم مختلف \nوصل لخباز في السوق، طلع له النقود إللي كانت معاه،\nالخباز شك في الشاب لإن النقود دي كانت عملات قديمة بقالها أكتر من ثلاثمائة سنة\nفشك إنه ممكن يكون لقى كنز بتاع حد، أو ممكن يكون جاسوس بسبب شكله المختلف عن أهل القرية كمان\nفنادى الخباز على جنود الشرطة إللي كانوا موجودين في المكان،\nفأخدوا الشاب للملك والشاب خايف طبعا، لإنه متوقع إن دلوقتي هيحصل إللي كان هو وأصحابه خايفين منه \nفلما دخّلوا الشاب للملك، الشاب استغرب!\nده ملك مختلف تماما عن الملك الكافر بتاعهم! \nسألهم الشاب عن الملك الكافر ، فقالوا إنه مات من سنين طويلة، وإن خلاص مابقاش فيه كفر لإنهم بقوا بيعبدوا ربنا دلوقتي!\nفالشاب اطمن وفرح جدا وبدأ يحكى قصته هو وأصحابه للملك المسلم، \nوالناس عرفتهم على طول لما حكى قصتهم ؛لإنهم كانوا مشهورين في البلد من ساعتها بسبب موقفهم المختلف تماما عن موقف باقي البلد من عبادة الأصنام،\nوعشان كمان اختفوا فجأة كإن الأرض انشقت وبلعتهم، فمش ممكن ينسوا حكايتهم بسهولة..\nوأخد الشاب الملك والجنود عند الكهف إللي فيه أصحابه عشان يقابلوا باقي الفتية، \nفلما قربوا من الكهف الشاب قال لهم إنه هيروح هو الأول يحكي لأصحابه إللي حصل ويخرج معاهم من الكهف ويتقابلوا مع الملك عشان لو أصحابه شافوا المنظر ده أكيد هيتخضوا جامد فهو خاف عليهم،\nوده يعلمنا مدى حرص الطيبين على قلوب بعض وإن الأخذ بأسباب عدم ترويع الآمنين، ده من صميم المروءة والشهامة وحسن الخلق والصلاح\nراح الشاب لأصحابه وحكالهم إللي حصل وإنهم قعدوا أكتر من ثلاثمائة سنة نايمين، \nوتيقن الجميع من قدرة الله وعظمته وحفظه المتين، \nوإن إللي خلّى مجموعة من الفتية يفضلوا نايمين السنين دي كلها، قادر على إحياء الموتى للجزاء والحساب ، يعني يوم القيامة قادم بدون أي شك\n\"وَكَذَلِكَ أَعْثَرْنَا عَلَيْهِمْ لِيَعْلَمُوا أَنَّ وَعْدَ اللَّهِ حَقٌّ وَأَنَّ السَّاعَةَ لَا رَيْبَ فِيهَا\nثم مات الفتية... ماتوا بعد ما أدوا رسالتهم .. \nمكنوش عارفين يدعوا قومهم والملك كان عايز يقتلهم.. فربنا خلاهم سبب في إن ناس تانية خالص توقن في موعود الله\n بعد سنين طويلة وبعد ظهور أجيال تانية جديدة مالهاش علاقة بيهم\nفدورهم مكنش في زمانهم على أد ما كان في زمن تاني خالص بقدر الله وتدبيره وحكمته\n\"وَكَذَلِكَ أَعْثَرْنَا عَلَيْهِمْ لِيَعْلَمُوا أَنَّ وَعْدَ اللَّهِ حَقٌّ وَأَنَّ السَّاعَةَ لَا رَيْبَ فِيهَا\"\n☆و احنا كمان.... \nممكن نشتغل ونشتغل ونشتغل، لكن ميكونش لينا دور بالسعي ده في وقتنا الحاضر..\nلكن يكون لينا دور السنة الجاية أو إللي بعدها أو حتى بعد سنين،\nأو حتى بعد ما نموت ممكن ربنا يبارك في أثرنا أكتر ما كان واحنا عايشين ويجعل دورنا يبدأ بجد في حياة الناس بعد مماتنا\nفتية الكهف تنازلوا عن حياتهم المرفّهة في القصور وجهروا بكلمة الحق،\nوالدافع إللي كان بيحركهم هو رضا الله فقط، محدش فيهم كان بيبص لمكانته الإجتماعية..محدش فيهم كان بيقول طب الناس هتقول عليّ إيه، طيب أصحابي ..طيب أهلي..طيب...طيب...محدش فيهم بص للكلام ده،\nمجرد ما عرفوا إن رضا ربنا في حاجة على طول عملوها لأنهم عارفين إن مهما عاشوا فنهايتهم الموت،\nيبقى يموتوا وهم محققين رضا الله ولهم الجنة، ولا إنهم يعيشوا في الدنيا في نعيم وربنا ساخط عليهم\nوعشان احنا كمان يكون لينا دور ،يبقى لازم نبذل لله أغلى ما نملك زي ما فتية الكهف بذلوا، \nومنخليش المكانة الاجتماعية أو أصحاب أو حتى أهل يصدوني عن البذل ده، \nلأ، أجاهد كل الصعوبات وأكمل طريقي، وبعدين استنى وقت حصاد الثمار لما ربنا يأذن\nبعد ما مات الفتية الناس اختلفوا وتنازعوا.. \n\"إِذْ يَتَنَازَعُونَ بَيْنَهُمْ أَمْرَهُمْ فَقَالُوا ابْنُوا عَلَيْهِمْ بُنْيَانًا رَبُّهُمْ أَعْلَمُ بِهِمْ قَالَ الَّذِينَ غَلَبُوا عَلَى أَمْرِهِمْ لَنَتَّخِذَنَّ عَلَيْهِمْ مَسْجِدًا \"\nيعني فريق قال نسد عليهم باب الكهف،\nوالفريق التاني قال لأ، احنا هنبني جنبهم معبد عشان يفكر الناس بقصتهم، وهيكون معبد مبارك بسبب صلاح الشباب دي.. \nوطبعا ده كان جائز في الشرائع إللي قبل كده، لكن شريعة الإسلام محرم فيها بناء المساجد على القبور وعمل المقامات والكلام ده \n☆يبقى نلخص أهم فايدة اتعلمناها من قصة النهاردة ونقول:\nإن فتية الكهف لما اتعرضوا للأذى الشديد إللي ممكن يكون سبب في إنهم يسيبوا دينهم هاجروا بدينهم..\nاعتزلوا الكفر وأهله وهربوا بدينهم.. فلما حفظوا دينهم ربنا حفظهم بحفظه المتين..\nوده يعلمنا إن أغلى حاجة في حياة الإنسان هي《دينه》، \nوإنه ممكن يتنازل عن أي شيء مهما كان في مقابل إنه يحافظ عليه، \nوإن إللي يبقى صادق فعلا زي فتية الكهف كده ربنا هينصره ويسّخر له الكون بمخلوقاته وقوانينه، لإن من كان مع الله كان الله معه\nقصتنا الجاية إن شاء الله هتكون عن صاحب الجنتين"}, {"n": 34, "l": "الجزء ٤٩ | صاحب الجنيتين", "u": "https://www.facebook.com/groups/710210019782034/permalink/755775948558774/", "t": "#قصص_الأنبياء\n#الحلقة_التاسعة_والأربعون\n#صاحب_الجنتين\nقصتنا النهاردة ربنا ذكرها في القرآن لرسول الله ﷺ وهي رسالة لكل إللي هيقرأ القرآن على مر السنين،\nعشان كفار قريش يعرفوا واحنا كمان نعرف إن العبرة مش بكثرة الأموال ولا بالغنى،\nولكن العبرة بالإيمان لأن الرجل ممكن يكون غني كافر ولا ينفعه ماله مثلكم يا كفار قريش\nوممكن يكون الإنسان فقير ولكنه مؤمن وهو ده إللي هينفعه يوم القيامة زي فقراء الصحابة إللي انتم طلبتم من رسول الله ﷺ إنه يطردهم عشان تقعدوا معاه وتسمعوا كلامه\nخلونا نشوف القصة مع بعض\nالقصة عن رجلين يُقال إنهم من بني إسرائيل، منعرفش في زمن أنهي نبي،\nلكن إللي يهمنا إن قصتهم بتتكرر في كل زمان، فلازم ناخد بالنا ونعتبر..\nالرجلين دول، واحد منهم غني ربنا أعطاله بستانين مليانين شجر من كل الثمرات، وخصوصا شجر العنب، لإنه أفضل الثمار ..\nوالمسافة إللي بين البستانين كمان مكنتش فاضية، \nلأ، ده ربنا جعل فيها كمان زرع ، ده غير إن من الأطراف الخارجية للبستانين النخل محاوط المكان من كل جانب.. فكان شكل البستانين جميل جدا وجذاب وكله نضارة وتناسق.. \nكمان موقع البساتين كان ممتاز،\nيعني  بيدخل له الهوا والشمس بشكل منتظم وصحي.. زي ما بنقول على شقة من الشقق مثلا: الشقة دي شِرحة وبِرحة ، جَوَّها بحري وهواها يرد الروح ويشرح القلب\nأهه البستانين بتوع صاحبنا ده كانوا من أحسن ما يمكن في كل شيء بالذات الموقع، فعشان كده الثمار طلعت على أحسن ما يكون..\nومش بس كده، ده الثمر إللي كان بيطلع مكنش فيه أي حاجة منه بتبوظ خالص أو تفسد \n\"وَاضْرِبْ لَهُمْ مَثَلًا رَجُلَيْنِ جَعَلْنَا لِأَحَدِهِمَا جَنَّتَيْنِ مِنْ أَعْنَابٍ وَحَفَفْنَاهُمَا بِنَخْلٍ وَجَعَلْنَا بَيْنَهُمَا زَرْعًا\"\nوكان لما يسقي الزرع في البستانين مكنش بيحتاج يحفر في الأرض عشان يطلع المياه الجوفية، \nولا كان بيحتاج إنه يجيب عُمال ينقلوا المياه للأرض عنده، ولا أي حاجة من دي،\nلأ، ده ربنا كان منعّمه ومريّحه أكتر، فكان مفجّر له نهر منها فيها والنهر ده كان بيمشي في البساتين ويرويها،\nوربنا جعل له زي عيون المية كده بتجري وسط البساتين من النهر ،فعلا سبحان الله حاجة تسحر العيون\n \n\"كِلْتَا الْجَنَّتَيْنِ آتَتْ أُكُلَهَا وَلَمْ تَظْلِمْ مِنْهُ شَيْئًا وَفَجَّرْنَا خِلَالَهُمَا نَهَرًا\"\nشوفوا النعم إللي ربنا أنعم بيها على الرجل دي كلها، \nعمل إيه هو عشان يشكر النعم دي\n☆شوفوا،\nالناس في شكر النعم أنواع: \n◇نوع بيتكبر ويطغى بالنعمة وبيعصي ربنا بيها، \nودول ربنا بيصبر عليهم لعلهم يتوبوا، ولما بيستمروا في معاصيهم وتكبّرهم، بيسلب منهم النعم دي أو بيموتهم عليها والعياذ بالله\nيعني مثلا تلاقي واحد ربنا مديله نِعم زي نعمة البصر ونعمة السمع،\nوبعدين تلاقيه بيستعملها في المعاصي ويتفرج على الأفلام والمسلسلات وبيسمع الأغاني..\nأو تلاقي واحدة ربنا معطيها نعمة زي نعمة الجمال، تقعد تستعرض جمالها قدام الناس وتخرج متبرجة في الشارع وتفتن الشباب..\nدول ممكن يفضلوا مستمرين في استعمال النعم في معصية الله لحد ما ربنا يسلبها منهم إن أراد عقابهم ولم يعفو عنهم.. \nكم مرة سمعتم عن بنت عملت حادثة وهي لابسة لبس مش كويس،\nوخرجت من الحادثة وهي مشوّهة أو محروقة أو عندها عاهة مستديمة والعياذ بالله قضت على جماله إللي كانت بتُبَارز ربنا بيه بالمعصية ليل نهار بدل ما تشكر النعمة كما  يحب ويرضى؟\nكم مرة سمعتم عن شاب عمل حادثة وهو بيسمع الأغاني وبدأ يطلّع في الروح، فحاولوا يلقنوه الشهادة لكن للأسف ما عرفش يقولها وفِضِل يردد الأغاني المحرمة لحد ما روحه طلعت؟\nشوفنا وسمعنا كتير عن حكايات زي دي، وكلهم هيُبعَثوا يوم القيامة وهمّ على المعصية دي، إن لم يعف عنهم الله، لإن من مات على شيء بُعث عليه\n◇النوع التاني من الناس هو نوع كل ما ربنا يزوّد له في النِّعم يتواضع لربنا ويشكر نعمته ويستعملها في طاعته عز وجل، وده ربنا بيمتّعه بالنعم دي حتى الممات.. \nكام مرة سمعنا عن واحد مات وهو ساجد أو صائم؟ \nدي ناس أفنت نعمة الصحة في تسخيرها في طاعة الله، وهو ده شكر النعمة.. \nكام مرة سمعتم عن بنت ماتت وهي بتقرأ القرآن؟\nأو بنت ماتت بحجابها مستورة مش باين منها شعراية حتى، رغم إنها ممكن تكون وقعت من مكان مرتفع مثلا ،\nالجزاء من جنس العمل يا جماعة، إللي يشكر نعمة ربنا ..ربنا هيبارك له في النعمة ويزودها له،\nواحنا شوفنا مثال على شكر النعم في سليمان عليه السلام وفي ذي القرنين،\nوإللي يكفر نعمة ربنا ويستعملها في معصيته ويتكبر بيها ويستغنى، ربنا هيسلبها منه في يوم من الأيام\nوربنا مهما أمهل الناس، فهو يمهل ولا يهمل..\nفالرجل صاحبنا بقى عمل إيه في النِّعم إللي ربنا أعطاها له\nللأسف كان من النوع الأول، تكبّر وطغى \nوالراجل ده كان له صاحب فقير فلوسه قليلة مش زي صاحبه،\nفي يوم من الأيام الراجل الغني قال لصاحبه الفقير: تعال نتمشى في البستان عندي شوية كده..\nدخلوا البستان على حالته إللي احنا وصفناها دي من الجمال والحُسن، وكان كمان ده وقت الحصاد فتخيلوا جمال المنظر\nلما دخل مع صاحبه البستان وورّاله الجمال، بدأ يتكلم ويجادله عشان يأثر عليه فقال له  بكل غرور:\nشايف أنا عندي أموال كتيرة إزاي؟!\nده غير مركزي الإجتماعي بين الناس ومكانتي بين الناس وقوتي ونفوذي بعشيرتي \n \n\" فَقَالَ لِصَاحِبِهِ وَهُوَ يُحَاوِرُهُ أَنَا أَكْثَرُ مِنْكَ مَالًا وَأَعَزُّ نَفَرًا\"\n☆عارفين زي إيه \nزي مثلا لما تلاقي واحدة مثلا من البنات إللي مش عايشة غير عشان تمتع نفسها بالدنيا، \nفعايشة حياتها بالطول والعرض ومش فارق معاها لا حلال ولا حرام، فتلاقي البنت دي لما تشوف واحدة من البنات الملتزمات بطاعة ربنا بما يرضي الله وثابتة على الحجاب الشرعي الساتر المظبوط، فتقول لها: \nشايفة أنا عايشة حياتي ومستمتعة بيها وبعمل كل إللي نفسي فيه إزاي\n؟!\nبخرج مع أصحابي في أي مكان براحتنا ومع أي حد براحتنا وفي أي وقت براحتنا ...\nوبسمع الأغاني وبتفرج على السينما والأفلام براحتي وبسافر هنا وهناك ، هي دي السعادة يا بنتي\nأنا عايشة حياتي أحسن منك.. أنا بستمتع بحياتي صح وانتِ دافنة نفسك بالحيا وهتضيعي عمرك في الخيمة إللي انتِ لابساها دي والحبسة إللي انتِ حطة نفسك فيها دي\nفهي نفس الحالة بالضبط\nالمهم، صاحبنا قال الكلمتين دول بكل فخر وغرور وتكبر،\nوكان داخل البستان من البداية بنفس الغرور ده، فبقى كل ما يبص على المكان وجماله يركبه الغرور أكتر.. \nوبدأ كلامه ياخد اتجاه واضح للكفر\nقال ياسلام عالجمال\nالجنة العظيمة دي إللي جذورها في الأرض والنخل إللي عمره سنين طويلة والمية الكثيرة دي مستحيل كده الجنة دي تفنى..إيه إللي يفنيها ..ده لو جراد الدنيا كله اتجمع مش هيقدر ياكلها\n\"وَدَخَلَ جَنَّتَهُ وَهُوَ ظَالِمٌ لِنَفْسِهِ قَالَ مَا أَظُنُّ أَنْ تَبِيدَ هَذِهِ أَبَدًا\"\nشايفين\nمن كتر غروره واستغناؤه بالنعمة عن المُنعم، بدأ يعتقد إن الجمال الشاسع ده الممتد شرقا وغربا وجذوره في أعماق الأرض وفروعه في عنان السماء، مستحيل إنه يفنى أو ينتهي ويزول\nطبعا هو بيكلم صاحبه الفقير ..مش يسكت بقى لأ ده كمل \nوقال لصاحبه الفقير :\nانت بتقول إن في يوم قيامة ويوم القيامة كل شيء بيهلك وينتهي\nطيب أنا بقولك إن مفيش يوم قيامة ..وحتى لو فرضنا جدلا يعني إن في يوم قيامة إللي أعطاني البساتين دي في الدنيا أكيد بيحبني وهيعطيني أحسن من البساتين يوم القيامة\n\"وَمَا أَظُنُّ السَّاعَةَ قَائِمَةً وَلَئِنْ رُدِدْتُ إِلَى رَبِّي لَأَجِدَنَّ خَيْرًا مِنْهَا مُنْقَلَبًا \"\n☆للأسف في ناس مفكرة إن لما ربنا بيعطيهم من نعيم الدنيا يبقى هو كده راضي عنهم..ومش فاهمين إن ربنا بيعطي الدنيا لمَن يحب ومَن يكره،  أما الآخرة فلا يعطيها إلا لمَن يحب\n\"وَلَا يَحْسَبَنَّ الَّذِينَ كَفَرُوا أَنَّمَا نُمْلِي لَهُمْ خَيْرٌ لِّأَنفُسِهِمْ ۚ إِنَّمَا نُمْلِي لَهُمْ لِيَزْدَادُوا إِثْمًا ۚ\"\nربنا لما يعطي الإنسان بيكون على حسب الشغل إللي بيشتغله ومدى إتقانه ليه، زي الغرب مثلا همّ دُوَل كافرة لكن بيشتغلوا صح في أمور الدنيا على أعلى مستوى،\nفربنا مديهم على أد شغلهم، هو أه متاع قليل.. لكنه متاع وأجر مكافيء لجهدهم وسعيهم\nاليابان مثلا عندهم تقدم رهيب ليه مع إنهم كفار؟\nلإن في سنن كونية ..اشتغل واتعب هتلاقي نتيجة حتما ولابد على أد شغلك، بغض النظر انت مؤمن ولّا لأ..\nفكثرة الأموال والأولاد أو قلتهم مش دليل أبدا على حب ربنا للإنسان أو كرهه له\n\"وَمَا أَمْوَالُكُمْ وَلَا أَوْلَادُكُم بِالَّتِي تُقَرِّبُكُمْ عِندَنَا زُلْفَىٰ \"\nوفي سورة الفجر، ربنا قال:\n \"فَأَمَّا الْإِنسَانُ إِذَا مَا ابْتَلَاهُ رَبُّهُ فَأَكْرَمَهُ وَنَعَّمَهُ فَيَقُولُ رَبِّي أَكْرَمَنِ ۩ وَأَمَّآ إِذَا مَا ابْتَلاهُ فَقَدَرَ عَلَيْهِ رِزْقَهُ فَيَقُولُ رَبِّي أَهَانَنِي ۩كلا\"\nيعني ربنا بيعلمنا إن الأمر مش كده خالص،\nالأمر فتنة واختبار في النّعم والنّقم: \n\"وَنَبْلُوكُمْ بِالشَّرِّ وَالْخَيْرِ فِتْنَةً\"\n◇عارفين تبقى علامة حب وتكريم امتى \nلما الإنسان يكون مؤمن وبيستعمل الأموال دي كلها في طاعة الله \nكان رد فعل الرجل الفقير إيه بقى\nالرجل الفقير كان مؤمن وكان شجاع.. \nلما سمع كلام صاحبه الكافر ده مقلش أنا فقير وهو غني ولو اتكلمت ونصحته ممكن يضرني أو يحرجني أكثر ويضايقني بكلامه، ومش بعيد يقهرني بعشيرته\n بالعكس ده كان معتز بدينه ودافع عن الحق بأسلوب راقي وبعلم وبحكمة وبحجج مُقنعة ومنطقية ومؤثرة\nوالمفروض كل صاحب حق يكون كده.. يتكلم بقوة وعزة بشكل يقع في نفوس الناس موقع مؤثر،\nمش يتكلم بخوف وتردد وارتعاش فالناس تستغل ده وترتاب في الحق وترده\n \nشوفوا كده الرجل الفقير المؤمن بيقول إيه:\n\"قَالَ لَهُ صَاحِبُهُ وَهُوَ يُحَاوِرُهُ أَكَفَرْتَ بِالَّذِي خَلَقَكَ مِنْ تُرَابٍ ثُمَّ مِنْ نُطْفَةٍ ثُمَّ سَوَّاكَ رَجُلًا ۩ لَكِنَّا هُوَ اللَّهُ رَبِّي وَلَا أُشْرِكُ بِرَبِّي أَحَدًا\"\nيعني بيقوله انت كفرت باللي خلقك من تراب وقادر زي ما خلقك من نطفة وخلاك رجل واقف بقوة وغرور كده إنه يهلكك\nوكمان بتقول مفيش يوم قيامة\nأما أنا فأنا أؤمن بأن الله ربي ولا أشرك به أحدا سبحانه\nثم ده بدل ما تحس بحياء من ربنا من كتر النعم إللي عندك، وتقول لا حول ولا قوة إلا بالله وما شاء الله كان بحوله وقوته وما لم يشأ لم يكن،\nوتقول الأذكار إللي تصون النعمة دي وتحفظها من العين والعُجب والزوال\n\"وَلَوْلَا إِذْ دَخَلْتَ جَنَّتَكَ قُلْتَ مَا شَاءَ اللَّهُ لَا قُوَّةَ إِلَّا بِاللَّهِ \"\nفكان أول حاجة الرجل المؤمن يعلمها للرجل الغني هي التوحيد لما قاله\n\"لَكِنَّا هُوَ اللَّهُ رَبِّي وَلَا أُشْرِكُ بِرَبِّي أَحَدًا\"\nوالرجل الغني ده عمل كمية خطايا وكوارث تودي في داهية\nهناخدهم واحدة واحدة \n◇الكارثة الأولى لما شكك في مجيء يوم القيامة،\nوالشك في يوم القيامة كُفر وتكذيب لله عز وجل\nلإن ربنا أقسم إن يوم القيامة والجزاء جاي، ومن صفات المؤمنين إنهم مصدقين لكلام ربنا كله بما في ذلك اليقين في يوم القيامة\nيعني مينفعش واحد مؤمن يقول :والله أنا هعبد ربنا وخلاص، طلع في يوم قيامة بجد يبقى أنا كنت صح وربنا هيجازيني\nطلع  مفيش يوم قيامة يبقى مخسرناش حاجة كيبرة \n \nالكلام ده ممكن نقوله فقط في المناظرات مع الملحدين، \nمن باب النقاش العقلي بالحجة،\nلكن عند المؤمنين المسائل دي قاطعة، لاااازم اليقين  100% إن فعلا في يوم قيامة وإن كل واحد هيتحاسب على أعماله السيئة وسيجازَى على أعماله الصالحة\n¤في هنا ملحوظة مهمة بالنسبة للدعوة\nهل كل الناس ينفع نحاورهم بالعلم زي ما صاحبنا المؤمن عمل مع الكافر\nلو حصل واتفتح قصادنا موضوع واحنا منعرفش عنه حاجة أو مش متأكدين من الكلام يبقى بلاش نتكلم لحد ما نجمع المعلومات الخاصة بالموضوع، \nيعني مثلا واحد جاي يتناقش معاك إن الأغاني مش حرام وإن الشيخ فلان قال والتاني قال والثالث..\nوانت معندكش العلم الكافي إنك ترد عليه أو معندكش القدرة على إقناعه يبقى متتكلمش،\nقول هراجع المسألة وأرد عليك أو استعين بحد تاني يرد عليه..ليه بقى\nعشان منضعِفش الحق\nوخصوصا لو مع ناس عايزة تجادل عشان الجدال ..هم مش عايزين الحق هم بيجادلوا وخلاص عشان التشويش، وبيبانوا على فكرة\nفهنا هيكونوا محتاجين لأسلوب أشد وإنك تخليهم يسكتوا خالص\nمثلا لما واحدة تيجي تسألك هو النقاب فرض ولا سنة وتسكت..دي بتبقى عايزة تعرف وتتعلم..غير إللي تيجي تقولك النقاب أصلا مش فرض ولا هو من الدين أساسا و..و... فالشخصية الأولى محتاجة نقاش معين والثانية محتاجة نقاش تاني خالص\n◇◇الكارثة الثانية إللي عملها الغني الكافر ده إنه تفاخر على صاحبه الفقير بما ليس عنده، والتفاخر كأصل منهي عنه، والنهي أشد لو هيكون تفاخر على فقير معندوش الأمور دي إللي بتفاخر بيها، فهو ظلم نفسه بسبب معصيته لله.\nوالإنسان بيظلم غيره لما ياخذ حقوقهم، ويظلم نفسه لما بيخليها تعصي الله\nفالناس ثلاثة أنواع :\n¤ظالم لنفسه بإنه ميعملش الفرائض،\n¤والنوع الثاني مُقتصد يعني يادوب بيعمل الفرائض أو الواجبات..يصلي الفرائض يصوم رمضان يؤدي الزكاة وهكذا بيعمل الفرائض إللي ربنا فرضها وبس،\n¤النوع الثالث بقى وهو السابق بالخيرات،\nوالنوع ده من اسمه أي حاجة يعرفها يعملها على طول ميفكرش بقى هي فرض ولا سنة،\nوصَل له فضل الصدقة تلاقيه بيتصدق،\nوصَل له فضل الذكر تلاقيه بيذكر ربنا على طول..وصل له فضل صلاة السنن تلاقيه ميسبش سنة وهكذا\nربنا يجعلنا منهم يارب\n◇الكارثة الثالثة إللي عملها: كانت إنه أصاب نفسه بالعين\nواحنا عارفين إن العين حق.. والعين على فكرة غير الحسد\nالحسد حاجة وحشة ، وهو إن الإنسان يتمنى زوال النعمة من عند الشخص التاني إللي عنده الحاجة الحلوة دي، عاوزها تزول من عنده وتبقى عندي أنا بس،\nأما العين فهي إني أُعجب بحاجة إعجاب شديد جدا ، زي صاحب الجنتين كده لما دخل البستانين بتوعه وأُعجب بيهم جدا ،\nدي عين مش حسد لإنه طبعا مش بيتمنى إن البساتين بتاعته دي تزول من عنده وتروح لنفسه تاني\nوعلى فكرة في الغالب بيحصل معانا أو مع غيرنا موضوع العين ده وبنكون فاكرينه حسد\nوعلى فكرة برده موضوع العين ده مش بيكون له علاقة بحب أو كره بين الناس زي الحسد كده والعياذ بالله،\nلأ، هي بتيجي تلقائية من غير ما الإنسان ياخد باله، بتيجي كعقاب على نسيان ذكر المُنعم عز وجل، زي قرصة وِدن كده تفكرنا عشان لو مرة على التانية نسينا نذكر المُنعم هننساه وننسى شكره مع الوقت والعياذ بالله\nفلما نشوف حاجة تعجبنا نفتكر إننا نقول :\n《ما شاء الله اللهم بارك》\n فلو هي حاجة بتاعتنا احنا شخصيا نقول:\n《ما شاء الله لا قوة إلا بالله》ولو هي حاجة بتاعة حد غيرنا نقول :《اللهم بارك》\nعشان كد الرجل الفقير المؤمن قال لصاحبه :\n\"وَلَوْلَا إِذْ دَخَلْتَ جَنَّتَكَ قُلْتَ مَا شَاءَ اللَّهُ لَا قُوَّةَ إِلَّا بِاللَّهِ\" \nفهو بيعلمه إزاي يتعامل مع النعم ودي تاني حاجة الرجل المؤمن علمها له\n◇الكارثة الرابعة إللي الراجل ده عملها: إنه أُعجب بماله والبساتين بتاعته 《إعجاب غلط》\nفي إعجاب صح وفي إعجاب غلط.. الإعجاب الصح إنك تستشعر بالفعل جمال النعمة عادي جدا وتنبسط بيها وتفرح، زي ما الحديث علمنا \"ثوبه جميل ونعله جميل\"، \nده مفيهوش حاجة،\nلكن العُجب الغلط هو إنك تبقى فرحان بالنعمة لإنك شايف إنك تستحقها بشطارتك وانك أهل للنعم لإنك إنسان جميل تستحق كل جميل..\nهو ده بقى المرض القلبي المُهلك والمحبط للعمل والعياذ بالله، وإللي لو صاحبه معالجهوش بيؤدي بيه للكفر زي صاحبنا ده والعياذ بالله\nومثال على كده إن واحد مثلا ربنا يوفقه لقيام الليل وصيام النهار، فييجي يشوف واحد بيشتكي إنه مبيصليش الفجر مثلا،\n فيدخل في قلبه عُجب ويقول بينه وبين نفسه: يا سلام عليّ أنا وعلى عزيمتي \nده مبيصليش الفجر لسه، ده أنا مش بس بصلي الفجر، لأ، ده أنا بقيم الليل وبصوم كمان\nفالعُجب ده أصلا محرم وفيه هلاك لصاحبه، \nوالإنسان بيتحرم من الطاعات بسبب إعجابه بنفسه ونسيانه إن إللي أنعم عليه بالطاعات دي هو الله وإن لولا توفيق ربنا مكنش الإنسان عمل أي طاعة\nالمصيبة بقى إن العُجب ده حاجة خفية أخفى من دبيب النمل \nفمن رحمة ربنا بينا إننا لما بنقع في العُجب واحنا مش حاسين إنه بيحرمنا من الطاعة دي مثلا ..عارفين ليه\nتخيلوا كده معايا إنسان عمال يعمل الأعمال الصالحة وقلبه فيه عُجب وجه يوم القيامة لقى معندوش أعمال صالحة خالص وضعه هيكون إيه\nبعكس لما الإنسان يتحرم من الطاعات أو النعم يبدأ يدور عن السبب ..يا ترى إيه إللي حصل ..ياترى أنا مبقتش أصلي قيام الليل ليه..مبقتش أصلي الفجر ليه..مبقتش أقرأ قرآن وأحفظ زي الأول ليه...وكل ماكان الإنسان صادق هتلاقي ربنا هداه إنه يعرف السبب ويعالجه\nالرجل المؤمن بقى لخّص لصاحبه الحوار كله في كلمتين وعلمه درس عظيم ..\nقال له لو انت فرحان بأموالك وأولادك وبتعايرني بفقري  وشايفني أقل منك في كل حاجة،\n\"إِنْ تَرَنِ أَنَا أَقَلَّ مِنْكَ مَالًا وَوَلَدًا\"\nوانت بتكفر بإللي أنعم عليك بالنعم دي وحرمني منها لحكمة عظيمة أنا مؤمن بيها بكل يقين؛\nفأنا ظني إن ربنا هيعاقبك على تصرفك وكلامك إللي قلته ده، ومش بعيد على ربنا إنه بين يوم وليلة زي ما رزقك يرزقني بنين وبنات وأموال وجنات وزيادة عليهم كمان،\nومش بس كده، لأ، ويرسل صواعق من السماء تحرق بساتينك وتساويها بالأرض لدرجة إن الناس تتزحلق من عليها من شدة ما بقت ملساء جرداء بلا زرع ولا ماء..\n\"فَعَسَى رَبِّي أَنْ يُؤْتِيَنِ خَيْرًا مِنْ جَنَّتِكَ وَيُرْسِلَ عَلَيْهَا حُسْبَانًا مِنَ السَّمَاءِ فَتُصْبِحَ صَعِيدًا زَلَقًا\"\nأو حتى من غير صواعق ولا حاجة ممكن في يوم وليلة ربك يجعل الماء إللي بيروي البساتين بتاعتك دي يجف ويغوص في الأرض ويتبخر في السماء،\n\"أَوْ يُصْبِحَ مَاؤُهَا غَوْرًا فَلَنْ تَسْتَطِيعَ لَهُ طَلَبًا\"\nومهما تحفر تاني متلاقيش المية ، فتموت جناتك دي كلها قصاد عينك وانت مش قادر تتصرف لإنك عبد ضعيف وربك هو الرزاق ذو القوة المتين،\nفمتتكبرش بنعمة إنت لا تملك حفظها من أمر الله ولا تملك صك إنها ليك انت لوحدك.. واتعلم إزاي تشكر وتصون النعمة، قبل فوات الأوان.. \nوفعلا نزل العقاب الإلهي\n\"وَأُحِيطَ بِثَمَرِهِ فَأَصْبَحَ يُقَلِّبُ كَفَّيْهِ عَلَى مَا أَنْفَقَ فِيهَا وَهِيَ خَاوِيَةٌ عَلَى عُرُوشِهَا وَيَقُولُ يَا لَيْتَنِي لَمْ أُشْرِكْ بِرَبِّي أَحَدًا \"\nهلك الثمر كله وهلكت البستانين كلها زي ما المؤمن قال.. \nوالغني الكافر جاحد النعمة بقى واقف مذهول بيضرب كف في كف من الصدمة ، \nوبقى يكلم نفسه من شدة الندم ويقول ياريتني ما أشركت بالله .. \nيا ريتني سمعت النصيحة الحق..\n يا ريتني شكرت ربي على النعم وأيقنت إني لا حول لي ولا قوة من دون الله\nفين عشيرته؟؟ فين أصحابه؟؟ فين الأغنيا الطاغين إللي زيه؟\n\"وَلَمْ تَكُنْ لَهُ فِئَةٌ يَنْصُرُونَهُ مِنْ دُونِ اللَّهِ وَمَا كَانَ مُنْتَصِرًا \"\nمفيش...\nكل إللي كان بيفتخر بيهم على الفقير، سواء مال أو أولاد أو عشيرة كله اختفى.. وبقى لوحده تماما...\nوحتى لو في حد حواليه فوجوده زي قِلِّته لإن مكنش يقدر يمنع عنه عقاب ربنا له أو ينصره من دونه عز وجل..\n\"هُنَالِكَ الْوَلَايَةُ لِلَّهِ الْحَقِّ ۚ هُوَ خَيْرٌ ثَوَابًا وَخَيْرٌ عُقْبًا \"\n يعني ياريته كان سمع كلام صاحبه الفقير المؤمن، لإن نصرة ربنا وثوابه المضاعف بيكونوا فقط لأولياؤه المؤمنين، لكن خلاص فات الأوان..\n☆وللأسف ده واقع كتير من الناس.. نقعد ننصح الواحد منهم وننبهه ونذكّره بالله، وهو مستمر ومعاند وسادد ودانه عن الحق، \nلحد ما في يوم تلاقي ربنا عاقبه في الحاجة إللي كان بيعصي ربنا بيها، \nوساعتها يندم أشد الندم، بس أوقات كتير بيبقى ندم حيث لا ينفع الندم وبيكون الإنسان خسر حاجات غالية أوي يفضل طول عمره متحسر عليها ومتألم من أثرها.. \nفياريت نتعلم من دروس قصص القرآن، بدل ما ندفع التمن غالي من حياتنا..\n◇والنوع ده، يعتبر النوع الأول من أنواع العقوبات، إللي هو النوع إللي ربنا بيعجّل له العقوبة في الدنيا\n◇أما النوع التاني، فده بقى إللي حتى لو ندم فندمه مش هينفعه لإنه بيكون ندم عند الغرغرة وسكرات الموت ،\nأو لإنه بيكون من إللي طغى واستكبر على الهداية واستحب الضلال فربنا طبع على قلبه وزاده ضلال على ضلاله لحد ما يموت،و ده إللي بتتأجل عقوبتهم  للآخرة\nتلاقي واحد ظالم طاغية وعايش زي ماهو عايز،  لحد ما يموت، لكن عقوبته مستنياه في الآخرة.. \nوتلاقي بنت ولّا شاب ماليين الأرض فجور ومعاصي وفسق وفجأة ربنا يقبض أرواحهم والعياذ بالله قبل ما ينزل بيهم أي عقاب دنيوي \n◇وفي نوع ثالث وهو النوع إللي ربنا بيعاقبه وهو مش حاسس،\nتلاقي الإنسان ربنا حرمه من الطاعات ومن القرب منه وهو مش واخد باله ومفكر إنه عشان جسمه سليم وبياكل وبيشرب وعنده مُتع الدنيا يبقى هو كده تمام \n \nوناسي إن أهم حاجة هي سلامة القلب لإن يوم القيامة يوم لا ينفع مال ولا بنون إلا من أتى الله بقلب سليم \nوده إللي بيسميه العلماء 《الاستدراج بالنعم》\nيعني ربنا يُنعم عليك رغم المعاصي، ساعتها لازم تقلق وتراجع نفسك وتعرف إنك مُستَدرَج،\nلإن النعم دي هتشغلك عن التوبة ومحاسبة النفس في المعاصي لإنها هتخليك تتخيل إن ربنا راضي عنك وقلبك بفتة بيضاء بقى وكده\nفييجي الموت فجأة وانت على الحال دي من الغفلة وساعتها مش هينفع الإنسان شيء\n \"فَلَمَّا نَسُوا مَا ذُكِّرُوا بِهِ فَتَحْنَا عَلَيْهِمْ أَبْوَابَ كُلِّ شَيْءٍ حَتَّىٰ إِذَا فَرِحُوا بِمَا أُوتُوا أَخَذْنَاهُم بَغْتَةً فَإِذَا هُم مُّبْلِسُونَ\"\nربنا يرزقنا جميعا القلب السليم إللي يكون سبب في دخولنا للجنة\n \nوبكده خلصت قصتنا النهاردة،\nوإن شاء الله المرة الجاية نتكلم عن قصة الأعمى والأبرص والأقرع \n●ملحوظة:\nإن شاء الله هكمل قصص الأنبياء بعد الجزء الجاي فهدخل في قصة يحيى وزكريا وعيسى عليهم السلام، وباقي قصص القرآن والحديث النبوي هتلاقوها في السيرة إن شاء الله"}, {"n": 35, "l": "الحلقه ٥٠ | الأقرع والأعمي والأبرص", "u": "https://www.facebook.com/groups/710210019782034/permalink/755968055206230/", "t": "#قصص_الأنبياء\n#الحلقة_الخمسون\n#قصة_الأبرص_والأقرع_والأعمى\nقصتنا النهاردة هي قصة الأعمى والأبْرص والأقْرع، حصلت القصة دي في بني إسرائيل في أي زمن بالتحديد أو إيه أسماء الثلاثة دول منعرفش\nلكن رسول الله ﷺ حكالنا القصة دي للعبرة،\nقال رسول الله ﷺ:\n\"إِنَّ ثَلَاثَةً في بَنِي إِسْرَائِيلَ أَبْرَصَ وَأَقْرَعَ وَأَعْمَى بَدَا لِلَّهِ أَنْ يَبْتَلِيَهُمْ..\"\nيعني كان في ثلاثة رجال من بني إسرائيل، واحد أعمى مش بيشوف، والتاني أبرص يعني عنده مرض البرص إللي هو بيكون أجزاء من الجسم لونها أبيض ومختلف عن باقي لون الجسم الطبيعي، ربنا يعافينا ويعافي كل مبتلى\nوالتالت أقرع معندهوش شعر..\nفربنا أراد إنه يبتليهم ويختبرهم...\n☆طيب ما همّ أصلا في بلاء، هيبتليهم أكثر من كده إيه\nأشد البلاء هو الإبتلاء بالنعم\nلإن الصبر على الشدة ناس كثير تقدر تحققه،\nزي الصبر على المرض والصبر على الفقر ، وهكذا ..\nوابتلاء الصبر على الشدة ده بيقدر عليه المؤمن والكافر زي ما قلنا قبل كده،\nيعني الواحد مضطر يصبر كده كده مفيش قدامنا حيلة إلا الاستسلام غالبا\nوالسبب في كده إن النفس البشرية بتكون متأهبة ومستعدة للتحدي والمواجهة، وعلى طول الإنسان يقوم يتضرع ويدعو ربه بخضوع وانكسار وتذلل عشان يرفع عنه البلاء،\nبعكس الإنسان إللي عايش في نعيم ومش بيواجه مشاكل، هتلاقيه مش في دماغه أصلا الاحتياج لشيء، وعايش حياته بالطول والعرض، ولو ذكّرناه بالله هيقول وهو أنا محتاج ربنا في إيه ما أنا كل أموري تمام\nعشان كده ربنا بيقول لنا:\n\"كَلَّا إِنَّ الْإِنسَانَ لَيَطْغَىٰ..أَن رَّآهُ اسْتَغْنَىٰ\"\nفالثلاثة دول لما كانوا في ابتلاء بالنّقَم يعني الشدائد كانوا خاضعين لله منكسرين،\nفربنا أراد إنه يبتليهم بالنعم عشان يشوفوا نفسهم هيبقوا عاملين إزاي،\nمع إن ربنا عالم باللي في قلوبهم لإن ربنا علام الغيوب وعليم بذات الصدور، \nلكن زي ما قلنا كتير قبل كده، ربنا مش بيحاسبنا على سابق علمه فينا، لكن على أعمالنا الفعلية وإللي هي مش غيب بالنسبة له عزو جل أبدا، فبيبتلينا عشان نشوف الحاجات المستخبية جوة قلوبنا، \nفينجو مننا إللي يُزكي نفسه ويعالج الأمور دي، ويَهلَك إللي يعمل نفسه مشفش حاجة ويكمل في الغفلة\nفربنا عمل إيه معاهم \nقال رسول الله ﷺ: \"فَبَعَثَ إِلَيْهِمْ مَلَكًا..\"\nيعني بعت لهم مَلك من الملائكة في صورة بشر عشان يسألهم أمنيتهم إيه؟\n\"فَأَتَى الْأَبْرَصَ فقال: أَيُّ شَيْءٍ أَحَبُّ إِلَيْكَ؟\"\nيعني المَلك راح للأبرص واتكلم معاه وبعدين سأله: نِفسَك في إيه، أو تتمنى إيه\nفالأبرص قال:\n\"لَوْنٌ حَسَنٌ وَجِلْدٌ حَسَنٌ، قد قَذِرَنِي الناس\"\nيعني أتمنى إن جلدي يكون حلو و لُوني يكون لون واحد مش لونين، وميكونش عندي إللي الناس بيبعدوا عني بسببه ده ويستغربوني \n\"فَمَسَحَهُ فَذَهَبَ عنه، فَأُعْطِيَ لَوْنًا حَسَنًا وَجِلْدًا حَسَنًا\"\nيعني المَلَك مسح على جلد الرجل الأبرص فاختفى البَرص، والرجل أخد إللي هو عايزه من اللون والجلد الجميل.. \nوبعدين المَلك سأله: أَيُّ الْمَالِ أَحَبُّ إِلَيْكَ؟ \nيعني إيه أكتر أنواع الأموال إللي بتحبها\nفالراجل قال له: الْإِبِلُ، فالمَلك أعطاه نَاقَةً عُشَرَاءَ وقال له: يُبَارَكُ لك فيها.\nيعني الملك إداله له ناقة حامل \n ودعاله بالبركة\n وبعدين سابه ومشي.. \nوراح المَلك للرجل الأقرع واتكلم معاه هو كمان وسأله تتمنى إيه؟\nفالأقرع قال: نِفسي  شعر راسي يرجع تاني؛ لإن الناس اشمأزوا منه ومن منظر راسي وشكلي\n \n=ويمكن كانوا بيضايقوه كمان بسبب إن همّ عندهم شعر وهو لأ=\n فأنا عاوز شعري يطلع تاني ويكون شكلي جميل\nفالملَك مسح على رأس الأقرع فطلع فيها شَعر جميل، \nثم سأله برده عن أكثر الأموال إللي بيحبها فقال له: البقر ، فالملَك اداله بقرة حامل\n ودعا له بالبركة، وبعدين سابه ومشي..\nوراح بعد كده للأعمى واتكلم معاه وسأله تتمنى إيه؟\nفالأعمى قال له : نفسي ربنا يرجع لي بصري عشان أشوف الناس\nفمسح الملك على عينه فبقى مُبصِر ، فسأله الملك هو كمان: بتحب إيه أكثر نوع من الأموال \nفقال : الغنم ، فاداله  شاة حامل \n .. ودعا له بالبركة وبعدها سابه ومشي..\nعدّت كم سنة والأبرص بقى عنده وادي من الإبل، والأقرع عنده وادي من البقر، والأعمي عنده وادي من الغنم.\nتخيلوا معايا كده يعني إيه وادي\nالوادي ده أرض منخفضة، حاجة كده زي الحوض الوااااسع، بيكون طوله آخر ما تجيب عينك من اليمين والشمال،\nفكل واحد منهم بقى عنده أرض مليانة بالإبل أو البقر أو الغنم\nوهنا جه وقت الإختبار\n \nبعد كام سنة رجع لهم المَلَك تاني ..\nالملك راح للرجل إللي كان أبرص في صورة رجل أبرص عشان يفكّره بنفسه زمان لو كان نِسي.. \nوقال له: \"رَجُلٌ مِسْكِينٌ تَقَطَّعَتْ بِيَ الحِبَالُ في سَفَرِي فلا بَلَاغَ الْيَوْمَ إلا بِاللَّهِ ثُمَّ بِكَ،\nأَسْأَلُكَ بِالَّذِي أَعْطَاكَ اللَّوْنَ الحَسَنَ وَالجِلْدَ الْحَسَنَ وَالمَالَ بَعِيرًا أَتَبَلَّغُ عليه في سَفَرِي\nيعني بيقوله أنا عابر سبيل، مُسافر غريب ومش معايا أي مال أكمل بيه سفري، ولا أشتري أكل،\nفمفيش حد يقدر يُعينني على سفري ده إلا الله ثم انت، فأسألك بالذي أعطاك الجلد الجميل واللون الجميل الذي أراه ، وأعطاك المال الكثير، إنك تديني ناقة واحدة أكمل بيها سفري،\n☆واخدين بالكم المَلَك عمّال بيذكّر الرجل إزاي بإن ربنا غيّر له كل ده وعافاه وكمان رزقه الأموال، من غير ما يحسسه إنه عارف الماضي بتاعه\nفالرجل إللي كان أبرص قال للملك المتخفي في هيئة مسافر فقير أبرص:\nإِنَّ الحُقُوقَ كَثِيرَةٌ\nيعني المسؤوليات إللي ورايا كبيرة... وأنا راجل عليّ ديون أد كده!\n☆بالرغم من تذكرة الملك للرجل بفضل ربنا عليه والعافية، إلا  إن الراجل للأسف ولا اتأثر \nابن السبيل من المستحقين للزكاة  أصلا \nفلو هو فعلا غني الغنى ده كله فأكيد عليه زكاة، ولازم يدفعها.. طب ما يدفعها لابن السبيل؟ \nولنفرض إنه خلاص دفع زكاة ماله من فترة،\nفهو غالبا برده بيكذب، لإن ديون كتيرة إيه دي إللي عليه، وهو عنده وادي مليان إبل\nثم هو لو مديون فعلا بديون كتيرة كده زي ما بيقول، ومع ذلك لسه محتفظ بالأموال دي كلها عنده يبقى مش كذاب ماشي أيوة، لكنه آكل لأموال الناس ومستحقاتهم المالية بغير حق! فهو كده أو كده مخطيء جدا ومتورط في المنكر حتى النخاع\nطيب الملك قال له إيه \nقال له:كَأَنِّي أَعْرِفُكَ!! أَلَمْ تَكُنْ أَبْرَصَ يَقْذَرُكَ الناس فَقِيرًا فَأَعْطَاكَ الله!\nيعني بيقوله أنا تقريبا عارفك\n مش انت إللي كنت أبرص وربنا أعطاك لون جميل وجلد جميل..؟ مش انت كنت فقير وربنا أغناك\nفالرجل قال له :لقد وَرِثْتُ لِكَابِرٍ عن كَابِرٍ\nيعني بيقوله انت بتقول إيه .. أنا ورثت المال عن أبائي وأجدادي.. إحنا عيلتنا كلهم أغنياء أصلا\n☆ده انت كذاب فعلا بقى... ومش  بس كذاب.. ده انت جاحد لنعمة ربنا كمان\nوده للأسف بقى وضع غالب في الناس دلوقتي إللي ربنا بيكرمها ويفتح عليها بالنعم بعد الشدة والفقر، إلا من رحم الله..\nوربنا بيقول عنهم :\n\"وَلَئِنْ أَذَقْنَاهُ رَحْمَةً مِّنَّا مِن بَعْدِ ضَرَّاءَ مَسَّتْهُ لَيَقُولَنَّ هَٰذَا لِي \". يعني أنا إللي عملت وأنا إللي تعبت وأنا إللي كسبت ده بشطارتي وأنا.. وأنا ..\nطيب فين فضل ربنا في حياتك..؟ مفيش\nوبالتالي انتم ماتزعلوش لما تُحسنوا لحد وتقفوا جنبه، وفي الآخر يتنكّر لكم.. \nماهو تنكّر لفضل ربنا الأول واستكبر بالنعمة على خلقه ولم يُرضي الله فيها بالشكر المطلوب.. فما بالكم بالبشر \nفالمَلك قال له :\"إن كُنْتَ كَاذِبًا فَصَيَّرَكَ الله إلى ما كُنْتَ\"\nيعني خلاص لو انت كنت كذاب فيارب ربنا يرجعك زي ماكنت \nوالملك سابه ومشي.... \nواتوجه للراجل التاني إللي كان أقرع،\nدخل عليه الملك في صورة إنسان فقير وأقرع وقال له نفس الكلام إللي قاله للأبرص، قال:\nأنا عابر سبيل .. مليش في الدنيا غير ربنا ثم إنت .. فاديني بقرة واحدة من كل دول، أكمل بيها سفري\nنفس اللي عمله مع الأبرص بالضبط وقعد برده يعظم له من حجم النعمة في قلبه والعافية..\nفالراجل قال له:\nالحقوق كتيييرة... دانا عندي ديووون... مش هقدر أديك حاجة\nفالملك قال له:\nكإني أعرفك؟! مش إنت كنت أقرع وربنا رزقك بشعر جميل؟! وكنت فقير وربنا أغناك\n؟!\nفالرجل قال له بانفعال برده: \nإزاااي تقول كده...!! ده أنا وارث المال من أبائي وأجدادي ..! أنا عمري ما كنت في يوم فقير \nفالملك قال له: لو كنت كاذب يارب ترجع زي ماكنت \n☆واخدين بالكم إزاي إن الإنسان ممكن يتمنى حاجة وتكون سبب في ضياع دينه\nزي مثلا لما أخت يكون نفسها تتزوج شخص معين وبتتوسل لربنا يزوجها له هو وبس وبتطلب ده في دعاءها بإلحاح، ومش قادرة تتخيل حياتها من غيره،\nلإنها مُعتقدة تماما إنها لو تزوّجته هتكون سعيدة ومش مُفوضة الأمر لله إللي أعلم منها بالخير من الشر،\nومتعرفش إنها ممكن لو تزوجته يكون سبب فتنتها أو سبب تعاستها، وياما سمعنا ده حصل \nأو مثلا واحد نفسه يدخل كلية معينة، ونفسه فيها وميعرفش إنها ممكن لما يدخلها دينه هناك يضيع ويموت على معاصي مع صحبة سوء عُمْر ما حد كان يتخيل إنه يوصل لها \nطيب الحل هنا إيه\nالحل في حاجتين :\n◇الأول هو الإستخارة في الحاجة إللي احنا عايزينها يعني نستخير ربنا ونقول دعاء الاستخارة، فلو الحاجة إللي احنا عايزينها فيها خير ربنا هييسرها لنا، ولو مفيهاش خير ربنا هيبعدنا عنها \n◇ وتاني حاجة هي الدعاء عموما\nيعني الاستخارة دعاء مخصوص لحاجة مخصوصة...لكن الدعاء عموما بيكون بشكل عام وعلى كل حال،\nفاحنا ندعي باللي نفسنا فيه كوووله مفيش مشكلة، بس في الآخر نقول يارب استجب لو ده كان فيه خير\nلإننا منعرفش نميّز الخير من الشر بِدقة، ومش كل إللي بندعي بيه وبنتمناه هو الخير، وربنا قالنا:\n\"وَعَسَى أَنْ تَكْرَهُوا شَيْئاً وَهُوَ خَيْرٌ لَكُمْ وَعَسَى أَنْ تُحِبُّوا شَيْئاً وَهُوَ شَرٌّ لَكُمْ وَاللَّهُ يَعْلَمُ وَأَنْتُمْ لا تَعْلَمُونَ\"\n☆عارفين بقى ليه نقول كلمة 《لو كان فيه خير》\n احنا كده بنعلّم نفسنا اليقين والتوكل على الله، وبنعلم نفسنا الرضا بقضاء الله،\nبمعنى إن أي حاجة هتحصل احنا راضيين لأننا عارفين ومتأكدين إن هو ده الخير\nوكمان عشان لو محصلش إللي احنا بنتمناه لحكمة ربنا يعلمها واحنا منعرفهاش...ميجيش الشيطان ويقول لحد فينا شوفت أهه ربنا مستجبش ومدكش إللي انت عايزه\nفين بقى ادعوني أستجب لكم...وفين إني قريب أُجيب دعوة الداع إذا دعانِ وفين..وفين...\nخلاص بطّل دعاء بقى ماهو مفيش فايدة\nوندخل في دوامة من الشبهات بسبب حاجة بسيطة خالص مكناش واخدين بالنا منها\nوحصلت مع ناس كتير للاسف\nفلمّا نقول مع الدعاء لو في خير؛ وقت لمّا ميحصلش...أول حاجة هنقولها: أيواااا ده مكنش فيه خير\n¤وهقول لكم معلومة عالسريع كده\nعارفين، كل دعوة بندعيها ربنا بيسجيبهالنا ١٠٠% بس هقول لكم عالسر \nمش لازم استجابة الدعاء تيجي زي احنا عايزين بالضبط\nلأن ربنا عالم الغيب بيعملنا أحسن حاجة مناسبة لينا \nيعني ولله المثل الأعلى،\nلو عندنا طفل صغير أخ أو ابن مثلا أو أي طفل بنحبه وطلب مننا حلاوة ياكلها واحنا عارفين إنه لو أكل النوع ده من الحلوى بطنه هتوجعه وسنانه هتسوس، هنديله الحلاوة دي ولّا لأ\nأكيد طبعا مش هنديله الحلاوة \nلأننا بنحبه واحنا عارفين إنها هتضره وخصوصا إنه صغير ومش عارف مصلحته،\nحتى لو زعل وعيط وصرخ وعمل إيه، وحتى لو هو مفهمش إننا بنعمل كده عشان مصلحته...حتى لو قالك انتِ مش بتحبيني ..حتى لو...حتى لو... وهتحاولي تقنعيه وتبيني له ضرر الحلاوة دي\nولله المثل الأعلى إحنا زي الأطفال بنطلب حاجة من ربنا وشايفين إنها جميلة، \nواحنا منعرفش إنها مضرة لنا، فربنا عالم الغيب يمنع عننا الحاجة دي عشان مصلحتنا ويعوضنا عنها مثلا بإنه يمنع عننا مصيبة كانت هتحصل لنا ،\nأو يدّخر لنا الدعوة دي، يحوشهالنا يعني ويجازينا بيها يوم القيامة؛ لأنه يعلم إن أعمالنا لما تتحط في الميزان مش هتكفي فيزودها لنا بالدعوات دي\nعشان كده رسول الله ﷺ قال:\n\"ادعوا الله وأنتم موقنون بالإجابة\"\nيعني هيستجيب هيستجيب لكن إمتى وإزاي دي اللي منعرفهاش\nممكن في الدنيا وممكن في الآخرة\nوجاء في الأثر عن رب العزة :\n《إن من عبادي المؤمنين من لا يُصلِحه إلا الغِنَى ولو افتقر لأفسدَهُ ذلك،\nوإن من عبادي المؤمنين من لا يُصْلحه إلا الصّحة ولو أسقَمْتُه لأفسده ذلك،\nوإن من عبادي المؤمنين من لا يصلحه إلا السّقم ولو أصْحَحَته لأفسده ذلك،\nوإني أُدبر لعبادي بعلمي بقلوبهم إني عليم خبير》\n☆ملحوظة:\n الحديث ده\n باللفظ ده ضعيف، لكن المعنى صحيح وفي حاجات عندنا في الشرع صحيحة بتؤدي نفس المعنى، عشان كده استشهدت بيه\nفاضل معانا في قصة التلاتة: الأعمى.. \nالملَك راح للراجل إللي كان أعمى، راحله برده في صورة بشر أعمى وقال له نفس الكلام :\nأنا عابر سبيل.. ماعنديش حاجة .. ماليش غير ربنا ثم إنت.. فاديني غنمة واحدة من كل دول أكمّل بيها سفري\nالأعمى قال له إيه بقااااا\nقال: \" قد كنت أَعْمَى فَرَدَّ الله بَصَرِي، وَفَقِيرًا فَقَدْ أَغْنَانِي فَخُذْ ما شِئْتَ فَوَاللَّهِ لا أَجْهَدُكَ الْيَوْمَ بِشَيْءٍ أَخَذْتَهُ لِلَّهِ\"\nيعني بيقوله :عارف.. أنا كنت أعمى زيك.. وربنا رد عليّ بصري وعافاني..\nوهو إللي أغناني بكل إللي انت شايفه ده بعد ما كنت في يوم من الأيام معنديش أي حاجة زيك كده... فخد إللي انت عايزه من كل ده وسيب إللي انت مش عايزه بس..\nفوالله أنا مش هراجعك في أي حاجة تاخذها\nفالمَلَك قال له:\n\"أَمْسِكْ مَالَكَ فَإِنَّمَا ابْتُلِيتُمْ فَقَدْ رضي الله عَنْكَ وَسَخِطَ على صَاحِبَيْكَ\"\nيعني خلي لك مالك كله ليك.. ربنا يبارك لك فيه.. \nده كان اختبار من ربك، وانت نجحت فيه، وربنا راضي عنك،  وسخط وغضب على صاحبيك: الأقرع والأبرص\n☆وهنا ييجي سؤال:\nإيه إللي خلى الأقرع والأبرص يسقطوا في الإبتلاء والأعمى هو إللي ينجح\nخليني أسأل سؤال ...هو إيه إللي بيخلي الإنسان يبقى عايز حاجة معينة\nيعني لو أنا ماشي في السوق مثلا، إيه الدافع إللي بيخليني أشتري اللبس ده وأشتري الذهب ده وأشتري الأجهزة دي.. وأشتري.. وأشتري...\nمش إللي خلاني أشتريها هو إن شكلها عَجَبني فقررت أشتري\nطيب لو أنا ما شوفتش الحاجة دي، هل هيكون في داعي جوايا إني أشتريها\nأكيد لأ.. أنا أصلا معنديش فكرة عن وجودها، أنا مشوفتهاش، أنا عيني ما اتعلقتش بيها..\nيعني باختصار من أعظم لذات الدنيا كلها هي 《النظر》 \n يعني يكاد يكون النظر يكون هو البوابة لكل الملذات الدنيوية،\nعشان كده ربنا بيقول في حديث قدسي : \n\"إِذَا ابْتَلَيْتُ عَبدِي بحبيبتَيْهِ –يعني عينيه- فَصبَرَ، عَوَّضْتُهُ مِنْهُمَا الْجنَّةَ\"\nفلما الإنسان يكون طول عمره عينه مقفولة عن الشهوات والمحرمات وفضول النظر .. قلبه هيكون عامل إزاي\nخلينا نشوف فوائد غض البصر:\n◇القلب هيكون كله تقوى وخشية من الله،\n◇ القلب هيكون فيه يقين ومحبة لله، ده غير البصيرة والفِراسة إللي ربنا هيرزقه بها ،\nوبكده الإنسان يقدر يفرق بين الحق والباطل ويفرق بين الشخص الصادق أو الكاذب ويعرف يطلّع الشخص المخادع\nده غير الراحة النفسية الكبيرة إللي الواحد بيكون فيها\nلأنه مش بيبص لصاحبه عند إيه، ولا بتبص لصاحبتها جايبة إيه في شقتها،\nولا بتحقد على جارتها إللي جددت شقتها وهي لأ، ولا غيرانة من أختها إللي اشترت ذهب وهي لأ، ولا...ولا...\nوعشان كده ربنا أمرنا بغض البصر مش بس عن المحرمات لأ ده حتى عن ملذات الدنيا\nقال الله تعالى:\n\"وَلا تَمُدَّنَّ عَيْنَيْكَ إِلَى مَا مَتَّعْنَا بِهِ أَزْوَاجًا مِنْهُمْ زَهْرَةَ الْحَيَاةِ الدُّنْيَا لِنَفْتِنَهُمْ فِيهِ وَرِزْقُ رَبِّكَ خَيْرٌ وَأَبْقَى\"\nفلما كان قلب الأعمى متحقق فيه الكلام ده\n ومتربي من زمان على عدم تعلق نظره بزخارف الدنيا، كان طبيعي جدا إنه ينجح في الإختبار \nفكان ابتلاؤه بالعمى، رحمة عظيمة له وأجمل رزق، من حيث لا يدري\n◇كلمة أخيرة،\nلو أخذتم بالكم احنا كل يوم بنتعرض للإبتلاء بتاع الأبرص والأقرع والأعمى واحنا مش واخدين بالنا \nممكن حد ييجي يطلب منك حاجة وانت ترفض بأي حجة زي حجج الأقرع والأبرص.. \nممكن يكون ربنا رزقك نعمة زي نعمة وظيفة معينة ونفوذ معين، وتقدر تخلص بيه مصالح للناس متعسرة ومن غير تعدّي على حقوق الآخرين أو ارتكاب أي محرم،\nومع ذلك تقوم انت تعطل مصالحهم وتبخل عليهم بنفوذك وإمكانياتك..\nوزي مثلا بعض دكاترة الكليات لما بيصعّبوا على الطلبة أحيانا الأبحاث ورسايل الماجستير والدكتوراة،\nويضغطوهم ويخنقوهم ويستقصدوهم ويرهبوهم ويصعبوا عليهم الإمتحانات،\nوهم كانوا في يوم من الأيام طلبة زيهم وفي مكانهم ويمكن حصل معاهم برده نفس التشديد والتعنت والتصعيب ده،\nومع ذلك لما ربنا عافاهم مراعوش ربنا في النعمة إللي اداها لهم وعافاهم من الحرمان منها قبل كده..\nوهكذا.. \nلو ركزنا في حياتنا هنلاقي إننا في امتحان مستمر زي امتحان الأبرص والأقرع والأعمى،\nلكن السؤال بقى إيه هو رد فعلنا على الاختبار ؟\nهل زي الأقرع والأبرص والعياذ بالله ؟\nولّا زي الأعمى\nإن شاء الله من الجزء الجاي هنرجع لقصص الأنبياء تاني وهنكمل باقي قصص القرآن والحديث النبوي في السيرة النبوية \nhttps://www.facebook.com/groups/710210019782034/?ref=share"}, {"n": 36, "l": "الحلقه ٥١ | آل عمران ___ زكريا مريم | الحلقه ٥٢ | زكريا", "u": "https://www.facebook.com/groups/710210019782034/permalink/755981045204931/", "t": "#قصص_الأنبياء\n#الحلقة_الواحدة_والخمسون\n#قصة_آل_عمران\n#مريم_زكريا_الجزء_الأول\nكنا واقفين قبل ما نبدأ قصص القرآن عند بني إسرائيل لما كانوا عايشين في بيت المقدس تحت الحكم الفارسي وبعدين تحت الحكم الإغريقي وبعدين تحت الحكم الروماني،\nوقلنا إن في حاكم روماني اسمه هِيرُودِس هو إللي كان بيحكم فلسطين،\nوالحاكم ده دخل اليهودية ولكنه كان ظالم وفاسد والكل كان بيكرهه حتى اليهود وقلنا إنه جدّد المسجد الأقصى ووسعه،\nده كان حال الوضع في فلسطين بصفة عامة، ندخل بقى للوضع في بني إسرائيل بصفة خاصة،\nبني إسرائيل إللي كانوا عايشين في فلسطين في الوقت ده كانوا من نسل يهوذا ..إللي كان فيه نسل ملوك بني إسرائيل،\nواحنا عارفين إن المُلك والنبوة اتجمعوا سوا تاني مع بعض لداوود وسليمان عليهما السلام\nفبني إسرائيل الموجودين تحت الحكم الروماني في فلسطين هم من ذرية داود وسليمان عليهما السلام\nكان في بني إسرائيل أهل بيت صالحين من العُبّاد، وكانوا من نسل سليمان عليه السلام،\nأهل البيت ده كان معروف بين بني إسرائيل بالتقوى والصلاح وكثرة العبادة وكان اسمهم :《آل عمران》\n\"إِنَّ اللَّهَ اصْطَفَى آدَمَ وَنُوحًا وَآلَ إِبْرَاهِيمَ وَآلَ عِمْرَانَ عَلَى الْعَالَمِينَ\"\nالأب اسمه عمران وكان كبير الأحْبار من اليهود يعني كبير العلماء، وكان الأحبار في بني إسرائيل بيرجعوا له في كل شيء، وزوجته كان اسمها حَنّة،\nوكان لها أخت اسمها أَشْيَاع وزوجها اسمه زكريا، ويقال إن أشياع دي بنتها، \nفالموضوع على خلاف بين العلماء \nالمهم في يوم من الأيام حَنة زوجة عمران شافت عصفورة بتأَكّل عيالها الصغيرين في العِش، فتحركت عاطفة الأمومة وبقى نفسها في طفل وكانت ساعتها كبيرة في السن،\n☆زي كده لما نشوف طفل صغير لسه مولود ويبقى نفسنا في طفل زيه،\nأو واحدة خلاص اكتفت من العيال بس لما تشوف طفل مع واحدة صاحبتها أو أختها، تشتاق نفسها للأطفال \nفده إللي حصل مع حَنّة زوجة عمران، اشتاقت للأطفال فدعت ربنا إنه يرزقها بطفل،\nونذرت إن إللي في بطنها ده هيكون لله، يعني عابد لله عشان ينصر الدين،\nوكان موضوع نذر الأولاد للعبادة ده في بيت المقدس مشهور عندهم، \nوتمّنت إن الطفل ده يكون ذكر عشان الذكر مختلف عن الأنثى في العبادة؛ لأن الأنثى بيجيلها وقت وتنقطع عن العبادة بسبب الحيض بعكس الذكر، ده غير قوة تحمل الذكر لأعباء الدعوة إلى الله،\n\"إِذْ قَالَتِ امْرَأَةُ عِمْرَانَ رَبِّ إِنِّي نَذَرْتُ لَكَ مَا فِي بَطْنِي مُحَرَّرًا فَتَقَبَّلْ مِنِّي إِنَّكَ أَنتَ السَّمِيعُ الْعَلِيمُ\"\nوفعلا حملت زوجة عمران لكن لما ولدت كان المولود أنثى\nفقالت يارب دي طلعت بنت\nوالولد مش زي البنت في العبادة\n\"فَلَمَّا وَضَعَتْهَا قَالَتْ رَبِّ إِنِّي وَضَعْتُهَا أُنثَى وَاللَّهُ أَعْلَمُ بِمَا وَضَعَتْ وَلَيْسَ الذَّكَرُ كَالأُنثَى \"\n☆طبعا ربنا يعلم إنها بنت وحَنة عارفة إن ربنا يعلم إنها بنت بس بتقول كده من باب مناجاة ربنا،\n يعني بتكلم ربنا و بتعبّر عن استغرابها وإن أمنيتها متحققتش مع إن نيتها كانت حلوة وربنا أعطاها عكس ماهي عايزة\nشوفوا بقى بالرغم من إن المولود طلع بنت مش ولد ..حنة زوجة عمران مقلتش خلاص يارب أهه إنت إللي قدّرت كده ..هعمل إيه يعني،\nفخلاص هرجع في النّذر بتاعي لأن مش ده إللي كنت مخططة له، وخلاص وهخلي البنت معايا وهستنى لما ترزقني بولد بقى \n لأ، دي صممّت إنها تكمّل في القرار إللي أخذته وتستغل النعمة المُتاحة إللي ربنا أعطاها لها عشان تحقق نيتها الحلوة برده\nالمهم....حَنّة زوجة عمران سمت البنت مريم، ومريم معناها العابدة،\nيعني كأنها بتقول لربنا:\nيارب ولد ولّا بنت خلاص إللي انت رزقتني بيه هستغله ومش هضيعه \nودعت ربنا إنه يعصمها من الشيطان هي وذريتها\n\"وَإِنِّي سَمَّيْتُهَا مَرْيَمَ وَإِنِّي أُعِيذُهَا بِكَ وَذُرِّيَّتَهَا مِنَ الشَّيْطَانِ الرَّجِيمِ\"\nودي صفات الإنسان الصادق في عبادته لربنا المُستسلم لقدر الله إللي مش بيتبع هواه..نشتغل بالموجود إللي ربنا أعطاه لنا \n☆وعايزين نقف هنا ياجماعة وقفة\nحنة زوجة عمران كان نفسها في حاجة معينة بصورة معينة وكانت نيتها فيها طيبة وخالصة لوجه الله،\nوده بيحصل معانا ساعات لما ندعي بحاجة معينة بصورة معينة وتبقى نيتك فيها طيبة،\nلكن ربنا يعطينا حاجة عكسها خالص..فنبدأ نشك في نفسنا ..نشك في حكمة ربنا والعياذ بالله والشيطان يبدأ يوسوس لنا وندخل في متاهات \nلما حنة ربنا أعطاها عكس إللي كان نفسها فيه عملت إيه\nاستغلت الموجود \nعارفين زي إيه\nواحدة نفسها تلبس النقاب وأهلها مش موافقين وبيمنعوها كل مرة تلبسه، \nوساعات بيقطعوا النقاب مثلا أو مش بيدوها فلوس تشتري نقاب أوغيره،\nوبيخلوها تخرج معاهم من غيره بالغصب وهي مغلوبة على أمرها في ده حاليا، ومش عارفة تلبسه،\nطيب هي تعمل بقى دلوقتي؟\nهل توقّف حياتها عند النقطة دي؟ \nطيب دي حاجة مش متاحة دلوقتي زي ما هي بتتمنى، خلاص يبقى تشوف إللي ربنا أتَاحُه لها و تُخلِص فيه النية بقوة وهمة عالية لحد ما ربنا يأذن بفتح الباب المقفول، \n مثلا عندنا الصلوات الخمس نحافظ عليهم مع السنن بتاعتهم،\nعندنا  القرآن نقرأ  ونحفظ ونتعلم.. عندنا صيام التطوع.. عندنا أخلاق عايزة تتظبط.. تقدر المرأة تلبس عبايات واسعة وتقدر تلبس خمارات طويلة، وتغطي على وشها بالخمار من الجوانب،\nوتقدري تلبس جوانتي، وممكن تلبس حتى قناع طبي ومحدش هيقدر يمنعها.... يعني كل دي أبواب مفتوحة، ليه بقى نجيي عند باب الطاعة إللي مغلوبين فيه على أمرنا و نقف \nوكذلك الكلام عن الشباب في مواقف حياتهم المشابهة..\nممكن واحد منهم يبقى نفسه يتعلم علم شرعي في مسجد على إيد شيخ بشكل دوري ومنتظم، \nوطلب ده من ربنا وربنا ميسّرش الباب ده لكن يسّر له أبواب تانية زي دورات النت ومعاهد العلوم الشرعية والدروس والكتب إللي على النت وفي المكتبات، \nهل معقولة يرفض ده كله ويقول طالما مش طلب في المساجد على إيد الشيخ وزي ما اتمنيت وخططت، يبقى مش لاعب؟ أكيد لأ\nفباختصار كده يا جماعة كلنا نستغل الرزق والأسباب المتاحة.. لا تدري لعل الله يحدث بعد ذلك أمرا\nومَا دُمْتَ مُلْزَمًا فاسْتَمْتَع \nزي ما حنة زوجة عمران عملت \nخلّونا نشوف بقى كان إيه نتيجة استسلام حنّة زوجة عمران\nلقضاء الله واستغلالها للمُتاح إللي ربنا وهبهولها \n◇أولا:\nربنا تقبل منها النذر بتاعها ، وكمان أنبت مريم نباتا حسنا ومُبارك فيه..  فكانت بتكبر في اليوم الواحد إللي كان بيكبره باقي الأطفال في سنة.. وجعل شكلها جميل ومنظرها مُبهج وقرة عين للي يشوفها،\n\"فَتَقَبَّلَهَا رَبُّهَا بِقَبُولٍ حَسَنٍ وَأَنبَتَهَا نَبَاتًا حَسَنًا\" \n◇ثانيا:\n كِبار العلماء تنافسوا على كفالتها، يعني بقوا يتجادلوا ويتنازعوا مين إللي ياخد باله منها ويراعيها،\nلأن بعد سنتين الرضاع حَنة أم مريم أخدتها للأحبار في بيت المقدس عشان تقعد هناك وتنقطع للعبادة وكان في الوقت ده أبوها عمران مات، فتنافس الأحبار على كفالة مريم،\nزي كده لما مثلا مجموعة من علماء زماننا يتنافسوا إنهم ياخدوا طفل صغير ويعلموه ويراعوه، فشوفوا مكانة الطفل ده إيه وسط الناس،\nوكان من ضمن العلماء دول نبي من الأنبياء اسمه زكريا،\nوكان زكريا عليه السلام نبي بني إسرائيل في الزمن ده،\nيعني مش بس العلماء إللي كانوا عايزين يكفلوا مريم، ده كمان نبي عايز يكفل مريم بنت عمران،\nلكن الأحبار كانوا رافضين،\n فقال لهم زكريا عليه السلام إن هو إللي هيكفلها لأنه زوج خالتها أو زوج أختها على اختلاف الروايات،\nفباقي الأحبار أعترضوا وقالوا لأ ..احنا نكفلها ..فعشان يطلعوا من الخلاف قالوا خلونا نعمل قرعة ..نرمي أقلامنا في الماء،\nوإللي قلمه يمشي عكس التيار هو إللي يكفل مريم،\nفلما رموا أقلامهم كان قلم زكريا عليه السلام هو إللي مشي عكس التيار فهو إللي تكفّل برعاية مريم،\nيعني هو إللي هيكون مسؤول عن تربيتها وتعليمها الدين والمسؤول عن رعياتها،\n\"وَمَا كُنتَ لَدَيْهِمْ إِذْ يُلْقُون أَقْلامَهُمْ أَيُّهُمْ يَكْفُلُ مَرْيَمَ وَمَا كُنتَ لَدَيْهِمْ إِذْ يَخْتَصِمُونَ\"\nكان زكريا عليه السلام بيعلم مريم الدين فكانت مريم بتتعبد في بيت المقدس في حتة في المسجد اسمها المحراب، والمحراب في لغة العرب يعني الجزء المبني المرتفع في المسجد، عارفين زي الصندرة بتاعة زمااان كده\nكانوا بيبنوا المسجد وبيبنوا جزء تاني قبل نهاية السقف كده بيكون زي دورين بس في مكان واحد،\nممكن تبصوا على الأوضة إللي انتم فيها كده..في نص الحائط تخيلوا كأن في سقف تاني زي كده \n  ----|  فالجزء إللي فوق ده المنعزل عن الناس كانوا بيناموا ويتعبدوا فيه وبيسموه المحراب\nفكان المحراب ده موجود في البيوت القديمة أوي وبعدين لما الناس نسيت إن ده محراب ومعمول للصلاة سموه صندرة وبقوا يخزنوا فيها الحاجات القديمة \nالمهم يعني مريم كانت بتتعبد في المكان ده وكانت معروفة بين الناس بعبادتها وتضرعها وقنوتها وخشوعها لله على الرغم من سنها الصغير\nوكانت لها كرامات، والكرامة زي المعجزة بتاعة الأنبياء والرسل، \nيعني حاجة خارقة للعادة ربنا بيجعلها على إيد بعض عباده الصالحين فالناس تعرف إنهم أهل خير وصلاح وتأييد من ربنا عز وجل، فهي للأنبياء والمرسلين اسمها معجزة أو آية، ولغير الأنبياء من أولياء الله الصالحين اسمها كرامة، \nمن الكرامات إللي ربنا وهبهالها، إن كان عندها فاكهة الصيف في وقت الشتاء وفاكهة الشتاء في وقت الصيف!\nوكان زكريا عليه السلام كل ما يدخل عليها في المحرب عشان يطمن عليها يلاقي عندها الفاكهة دي فيستغرب،\nويسألها يامريم الفاكهة دي بتيجي منين \n\"كُلَّمَا دَخَلَ عَلَيْهَا زَكَرِيَّا الْمِحْرَابَ وَجَدَ عِندَهَا رِزْقًا قَالَ يَا مَرْيَمُ أَنَّى لَكِ هَذَا\"\nفكانت مريم عليها السلام بتقول له :\n من عند ربنا، هو في حد بيرزق عباده غيره \n\"قَالَتْ هُوَ مِنْ عِندِ اللَّهِ إِنَّ اللَّهَ يَرْزُقُ مَن يَشَاء بِغَيْرِ حِسَابٍ\"\n☆خدوا بالكم إن ربنا بيهيأ مريم نفسيا بالكرامات دي عشان \nتطمن على نفسها ؛ لأن في أمر عظيم هيحصل في حياتها بعدين ويعتبر هزة جامدة لأي واحدة قانتة وتقية زيها،\nفلما مِن وهي صغيرة تتعود إنها تشوف الكرامات دي وتتعلم إن ربنا على كل شيء قدير وإن دي علامات لقبول طاعاتها وصلاحها وعاجل بُشرى ليها من ربنا بالخير والرضا؛\nهتقدر تتقبل وتواجه الأحداث إللي هتحصل بعدين\nوالكلام ده ينبهنا لنقطة مهمة وهي إن كل ما كان الإنسان من صُغره بيتعرض لمواقف بيربي فيها نفسه... كل ما كان قادر إنه يتحمل ظروف الحياة،\nفلما تلاقي نفسك في ابتلاءات مستمرة وبتتعلم منها اعرف إن ربنا بيجهزك لدور معين في المستقبل محدش هيقدر يقوم بالدور ده غيرك\n◇طب إيه بقى إللي هيحصل مع مريم رضي الله عنها \nمش لما نعرف الأول إللي حصل مع زكريا عليه السلام \n لإن إللي حصل مع زكريا عليه السلام كان من ضمن التهيئة إللي ربنا عز وجل بيهأ مريم ليها نفسيا\n☆قبل ما نعرف إللي حصل مع زكريا عليه السلام عندنا معلومة عايزين نعرفها وهي إننا ينفع نقول عن مريم: \n《عليها السلام》 أو 《رضي الله عنها》،\nوكلمة عليه السلام أو رضي الله عنه بصفة عامة تجوز في حق أي إنسان مسلم صالح،\nيعني يجوز مثلا نقول مصطفى رضي الله عنه، أو كريم عليه السلام، \nلكن المشكلة إننا نثبّت الكلمة دي في كل مرة بنذكر اسم الشخص ده، لإنها بتوْهم السامع إنه يا إما نبي يا إما صحابي، بالذات عليه السلام بتوهم جدا إنه نبي،\nعشان كده الصح إننا ننوع بين اللفظتين عند ذكر مريم، لإنها بالفعل مش حد عادي، هي مكانتها عالية وربنا اصطفاها على نساء العالمين لكنها مش نبية \nنرجع لزكريا عليه السلام،\nكان زكريا عليه السلام نبي بني إسرائيل في الزمن ده زي ما قلنا، وهو من ذرية سليمان عليه السلام، \nوقلنا إنه كان متزوج من خالة مريم أشياع.. وكان زكريا بيشتغل نجار، وكان كبير في السن كان عمره حوالي تسعة وتسعين سنة،\nوكانت زوجته عمرها ثمانية وتسعين سنة،  ومكنش عنده أولاد..\nفلما دخل على مريم وشاف عندها الفاكهة والرزق الواسع العجيب ده، وسألها وقالت ده من عند ربنا اللي بيرزق من يشاء بغير حساب؛\nكإن مريم بجوابها ده نبّهت زكريا عليه السلام لمعنى عظيم ، وهو إن إللي بيرزق مريم في محرابها بالرزق العجيب وإللي بدون أي أسباب دنيوية، قادر إنه يرزقني الولد وأنا كبير في السن كده.. \n☆زي كده لما نكون حافظين آية معينة من القرآن، زي آية: \"الَّذِينَ إِذَا أَصَابَتْهُم مُّصِيبَةٌ قَالُوا إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ \"، وبعدين يموت حد من معارفنا إللي بنحبهم، فنسمع حد  بيقول لنا:\n\"احنا كلنا راجعين عند ربنا، إنا لله وإنا إليه راجعون\" \nفبنحس كأننا بنسمعها لأول مرة.. مش عشان احنا مش حافظين الأية ولا عارفينها،  لأ.. لكن لأن مكنش لسه جه موقف يعبر عنها أوي فبالتالي تأثر فينا التأثير ده،\nفنبدأ نستحضر معناها من تاني كإننا أول مرة نسمعها أو كانت تايهة عننا ولقيناها\nفلما زكريا عليه السلام شاف الفاكهة عند مريم وهي في غير الموسم بتاعها، وقالت له إن السبب هو إن ربنا بيرزق من يشاء بغير حساب، وهو كان عارف طبعا من زمان إنه ربنا بيرزق من يشاء بغير حساب \n \nلكن هنا وبعد جملتها، وقع المعنى في قلبه عليه السلام وكإنه أول مرة يلمس المعنى ده بإيده بشكل قريب ومباشر،\nيعني كإنه حدث نفسه وقال لها:\nيعني ربنا رزق الطفلة الصغيرة دي بأعاجيب الرزق بفضل منه وبدون ماهي تدعي أو تطلب، \nأومال أنا بقى لو دعيت ربنا هيحصل إيه\nفعلى طول دعا زكريا عليه السلام ربنا  باللي بيتمناه وكان فقد فيه الأمل بسبب انقطاع أسبابه الدنيوية عنه\nيا ترى زكريا دعا بإيه، وهل لما دعى، ربنا استجاب دعاؤه ولّا لأ؟\nده إللي هنعرفه الجزء الجاي إن شاء الله\n#قصص_الأنبياء\n#الحلقة_الثانية_والخمسون\n#مريم_زكريا_الجزء_الثاني\n#زكريا_يحيى\nاتكلمنا المرة إللي فاتت عن زكريا عليه السلام لما كان بيدخل على مريم الطفلة الصغيرة عشان يعطيها الأكل بتاعها ،\nفكان بيلاقي عندها فاكهة الصيف في الشتاء ،\nوفاكهة الشتاء في الصيف، فلما سألها قالت له إن ده رزق من عند ربنا\nفوقع في قلب زكريا عليه السلام إن ربنا حقق للطفلة الصغيرة دي كرامة وأعطاها الفاكهة من غير ما تطلب،\nأمّال لو أنا بقى دعيت وطلبت بقى ..أكيد ربنا هيستحيب،\nحتى ربنا مقالش في القرآن فدعا زكريا لأ..ده قال:\n\"هُنَالِكَ دَعَا زَكَرِيَّا رَبَّهُ \"\nفكأن زكريا عليه السلام جت له فرصة فاغتنمها\nيعني يارب إنت إديتها حاجة عجيبة من عجائب الأرزاق من غير ماهي تسألك، \nلكن أنا يارب هسألك فيا ترى عطائك هيكون إزاي لمن يسألك\nودعا زكريا وقال:\n \"رَبِّ هَبْ لِي مِن لَّدُنكَ ذُرِّيَّةً طَيِّبَةً إِنَّكَ سَمِيعُ الدُّعَاء\"\nيعني يارب هب لي ذرية طيبة على الرغم من كبر سني وشعري إللي شاب وعقم زوجتي.. يا سميع الدعاء يا مَن ترزق من تشاء بغير حساب\n☆طيب هو ليه زكريا عليه السلام قال لربنا : \"هب لي\" ومقلش \"أعطني\"\nلأن الهبة لا يُحاسَب عليها الشخص إللي هيوهبها لي لو لم يهبها لي\nبمعنى إن أنا لو اديتك هِبة فده فضل من عندي، ولو منعتك الهبة دي فانت ملكش أي حق إنك تزعل أو تضايق، \nبعكس لو جيت طلبت مني شيء، وأنا منعته عنك ممكن ساعتها تزعل.. \nننزّل الموقف على زكريا عليه السلام:\nهو طلب من ربنا الهبة، بمعنى إنه لو إداله الطفل هيبقى كرم وفضل من ربنا عليه عز وجل ،\nولو منعه الطفل، فخلاص مش مشكلة مش هيزعل إن ربنا منع عنه شيء لإنه أصلا بيطلبها وهو شايف إن ملوش حق فيها ولا يملك حاليا أسباب الهبة إللي بيطلبها دي، وكله هيبقى أولا وأخيرا بفضل ربنا..\nوده يعملنا جانب من أدب الأنبياء في الدعاء عليهم السلام\nتعالوا كده نحلل دعاء زكريا عليه السلام ونشوف إزاي دعا ربناو نتعلم منه \n◇أول حاجة، زكريا عليه السلام كلم ربنا بينه وبين نفسه، مناجاة في الخفاء من غير ما حد يسمعه..\n\"إذْ نَادَى رَبَّهُ نِدَاء خَفِيًّا\"\nقال:\nيارب متسبنيش من غير ولد ولا وارث يرث النبوة من بعدي وأنت خير الوارثين\n\"وَزَكَرِيَّا إِذْ نَادَىٰ رَبَّهُ رَبِّ لَا تَذَرْنِي فَرْدًا وَأَنتَ خَيْرُ الْوَارِثِينَ\"\n☆واحد عايش بقاله مائة سنة تقريبا بيطلع يشوف الناس ، فلان معاه أبناؤه بيلعب معاهم، وده أبناؤه بياخدوا بالهم منه وده..وده..\nمائة سنة.. ماسمعش كلمة بابا.. مش هيحس بإحساس زكريا عليه السلام غير إللي اتحرم من نعمة الذرية...\nيارب يرزق كل مشتاق ذرية صالحة \n☆عارفين بقى زكريا عليه السلام حالته من ناحية التشخيص الطبي إيه\n؟\nرجل وزوجته داخلين على مائة سنة.. هي عاقر وهو شيخ كبير عجوز.. يعني من الناحية الطبية استحاااالة إنهم يخلفوا أطفال\nفكان زكريا عليه السلام بيدعو في الخفاء بالليل بينه وبين ربنا... متخيلين لو الناس سمعوه وهو بيدعي بإن ربنا يرزقه طفل، وهو ظروفه زي إللي قلناها كده.. الناس هيكون رد فعلهم إيه\n◇تاني حاجة بدأ زكريا عليه السلام الدعاء بأنه أظهر الفقر والضعف والذل لله\nقال : يارب أنا عظمي بقى ضعيف يعني لو انت شايفني واقف لكن انا عظمي ضعيف\nوشعر رأسي شاب كله، وأنا عمري ما دعيتك قبل كده ورديت دعائي،\n\"قَالَ رَبِّ إِنِّي وَهَنَ الْعَظْمُ مِنِّي وَاشْتَعَلَ الرَّأْسُ شَيْبًا وَلَمْ أَكُن بِدُعَائِكَ رَبِّ شَقِيًّا\"\n☆خدوا بالكم إن في أدعية ربنا بيستجيبها لنا من غير ما ندعي بيها\nيعني انت النهاردة دعيت ربنا إنه يحفظ لك بصرك؟\nدعيت ربنا إنه يحفظ لك سمعك، جسمك، عيالك، والدتك، والدك، بيتك إللي إنت ساكن فيه، موبايلك إللي معاك دلوقتي، إلى آخر كل النعم إللي احنا غارقانين فيها ليل نهار؟\nطيب ولما مش بتدعي إن ربنا يحفظهم؟ مين إللي بيحفظهم من غير دعاءك؟ الحفيظ عز وجل..\nنِعم كتير أوي ربنا حافظها لنا من غير ما ندعي بس احنا مش واخدين بالنا \n◇تالت حاجة بقى قال لربنا في الدعاء السبب هو ليه عايز الولد، فقال :\n\"وَإِنِّي خِفْتُ الْمَوَالِيَ مِن وَرَائِي وَكَانَتِ امْرَأَتِي عَاقِرًا فَهَبْ لِي مِن لَّدُنكَ وَلِيًّا.. يرِثُنِي وَيَرِثُ مِنْ آلِ يَعْقُوبَ وَاجْعَلْهُ رَبِّ رَضِيًّا\" \nيعني يارب أنا خايف إني أسيب أحبار اليهود يُفسدوا على بني إسرائيل دينهم ومفيش نبي غيري دلوقتي، وكمان زوجتي عاقر لا تلد\nفيارب اوهبني من رحمتك ذرية \nلكن مش أي ذرية أنا مش عايز ولد كده وخلاص، لأ أنا عايزه يكون ذرية طيبة يرثني ويرث من آل يعقوب النبوة..\nفاستجاب الله دعاء زكريا عليه السلام\nومش بس كده\nده ربنا أرسل له الملائكة عشان تبشره وتقوله:\n\"يا زَكَرِيَّا إِنَّا نُبَشِّرُكَ بِغُلامٍ اسْمُهُ يَحْيَى لَمْ نَجْعَل لَّهُ مِن قَبْلُ سَمِيًّا\"\nيعني يا زكريا، احنا ملائكة الله جايبين لك البشارة من ربنا إنه استجاب دعاءك وهيرزقك بولد اسمه يحيى من أحسن البشر وأشرفهم، \nومن شرفه وعلو مكانته ربنا بنفسه عز وجل هو إللي سمّاه،\nومش أي اسم، ده اسم مفيش حد قبل كده على الأرض اتسمّى بيه\nيعني الملايكة بتبشره بمجموعة من الأخبار السعيدة، \nمش بس بتبشره بطلبه فقط، \nلأ، ده زيادة عليه كمان حاجات عمره ما كان يتخيل إنه يطلبها أو تكون من نصيبه\n☆عارفين زي إيه ولله المثل الأعلى\nزي لما تكون بتدوّر لابنك أو بنتك على اسم جديد ويكون معناه حلو، ثم حد بتحبه قال لك اسم جديد وجميل محدش سمّاه قبل كده، \nفتسمي ابنك بالاسم ده وكل ما حد يسألك عن اسمه تقولي ده فلان هو إللي سماه وهو أول طفل يتسمى بالاسم ده\nفكان ده الوضع مع زكريا عليه السلام، فرحته بالاسم والبشرى وتسمية الله لابنه وكل ده، كانت أعظم مما نتخيل،\nومش بس كده، شوفوا البشريات التانية:\n\"أَنَّ اللَّهَ يُبَشِّرُكَ بِيَحْيَى مُصَدِّقًا بِكَلِمَةٍ مِّنَ اللَّهِ وَسَيِّدًا وَحَصُورًا وَنَبِيًّا مِّنَ الصَّالِحِينَ\"\nيعني هيكون سيد وحصور\nو \"سيد\" يعني شخص كلمته مسموعة وليها أثر في الناس وبيتبعه ناس كتير،\nوحصُور يعني معصوم من الذنوب فلا يأتيها،\nيعني كإنه حُصِرَ عنها فبقى مانع نفسه من الشهوات الضارة ومن إنها تأثر عليه ومش بس كده، ده كمان نبي من الأنبياء \nيعني هو طلب ذرية طيبة ربنا رزقه فوق ماكان يتخيل\nتعالوا بقى نشوف كده إيه ممكن تكون الأسباب إللي تخلي ربنا يعطي زكريا عليه السلام النعم دي كلها ويحقق له المعجزة دي\nعارفين الملائكة لما راحت تبشر زكريا عليه السلام بالولد كان فين وبيعمل إيه \nكان واقف بيصلي في المحراب بتاعه\n\"فَنَادَتْهُ الْمَلائِكَةُ وَهُوَ قَائِمٌ يُصَلِّي فِي الْمِحْرَابِ \"\n¤ واحنا قلنا يعني إيه محراب المرة إللي فاتت \nيعني الملائكة مجتش لقيته نايم مثلا ، لأ، ده دعا ربنا باللي هو عايزه وفضل مكمّل في عبادته،\nيعني ما دعاش وهو تارك للعبادة، لأ ده دعا، و مخلاش أمنيته تشغله عن محرابه، وكمل عبوديته لله الحق على أكمل ما يكون،\nولا قال أنا هدعي وهجرب كده وأشوف ربنا هيستجيب لي فأكمل عبادة ولّا لأ، زي ما في ناس بتعمل للأسف\nودول ربنا قال عنهم:\n\"وَمِنَ النَّاسِ مَن يَعْبُدُ اللَّهَ عَلَىٰ حَرْفٍ فَإِنْ أَصَابَهُ خَيْرٌ اطْمَأَنَّ بِهِ ۖ وَإِنْ أَصَابَتْهُ فِتْنَةٌ انقَلَبَ عَلَىٰ وَجْهِهِ خَسِرَ الدُّنْيَا وَالْآخِرَةَ\"\nفالنوعية دي بتبقى بتعبد ربنا بمزاجها ولمزاجها، وعاملين زي بني إسرائيل كده، بيجربوا،\nمفيش يقين، وعندهم ريبة وشك وتذبذب، وبيشترطوا على ربنا في العبادة وعاوزين ربنا يعمل لهم إللي نفسهم فيه، وبكده تبقى الحياة وردي وتمام التمام\n \nلكن لو ربنا عمل معاهم غير إللي همّ كانوا متصورينه أو متوقعينه، زي مثلا أخّر عنهم تحقيق الدعاء أو أعطاهم شيء تاني بدل إللي طلبوه ولم يُعطهم إللي عايزينه، \nأو ابتلاهم بدل ما يعطيهم، هنا بقى يشتغل سوء الظن في الله ويبقى الواحد من جواه ساخط على ربنا وأقداره وتدبيره وتصريفه  للأمور،\nإللي هو: إيه ده ؟!.... ده أنا مكانش بيحصل لي كده وانا بعمل المعاصي\nبقى بعد ما أتوب وأرجع لك وألجأ لك يحصل لي كل ده؟ يعني ياربي هو ده جزائي إني سيبت المعاصي وسيبت التوسل بالقبور وتركت الدجالين والمشعوذين؟! \nوإزاي يارب ..وليه يا رب .. واشمعنى يا رب... طب خلاص بقى انا أرجع لحياتي إللي قبل كده وكنت بعمل إللي انا عايزه \n \nزكريا عليه السلام ماعملش كده.. زكريا دعا وكمل في طريق العبادة\nفربنا استجاب له ووهب له يحيى وفوق منهم عطايا تانية فوق ما كان يتخيل..\n\"فَاسْتَجَبْنَا لَهُ وَوَهَبْنَا لَهُ يَحْيَىٰ وَأَصْلَحْنَا لَهُ زَوْجَهُ ۚ إِنَّهُمْ كَانُوا يُسَارِعُونَ فِي الْخَيْرَاتِ وَيَدْعُونَنَا رَغَبًا وَرَهَبًا ۖ وَكَانُوا لَنَا خَاشِعِينَ \"\nفكان سبب الإستجابة إن هو وزوجته إشْياع كانوا طول عمرهم بيعملوا ثلاثة أشياء ميعملهاش غير الصادق وإللي غايته فعلا رضا ربنا وهم:\n◇ أولا:《كانوا يسارعون في الخيرات》\nأي حاجة فيها خير مش بس بيعملوها، لأ.. دول كانوا بيسارعوا فيها.. مفيش تسويف.. مفيش تأجيل.. وأي حاجة كانت تغضب ربنا كانوا يسيبوها فورا.. مفيش تباطؤ.\n◇ثانيا: 《يدعوننا رغبا ورهبا》\nيعني بيدعوا ربنا برجاء وخوف.. برجاء يعني بطمع في كرمه إللي ملوش حدود، عشان يرزقهم  إللي عنده بكرم ويكون عند حسن ظنهم في واسع كرمه.. \nو بخوف يعني خوف من عقابه وعذابه ومن عدم قبوله لأعمالهم فيدخلوا على الآخرة من غير ما يكون عندهم أعمال فيدخلوا النار والعياذ بالله، \nفبيدعوا ربنا خوفا من عقابه عشان يصرفهم عنه وعن عذابه،\nفكانوا عارفين زي ما ربنا غفور رحيم فهو شديد العقاب،\nوهو ده تمام الإيمان؛\nلإن الإيمان لا يكتمل ولا يقوم إلا بالرجاء والخوف مع بعض، زي الطير كده ما يعرفش يطير بجناح واحد.. \nوالنبي ﷺ قال: \"لو وُزن خوف المؤمن ورجاؤه لَاعْتَدلا\"\nثالثا: 《كانوا لنا خاشعين》\nيعني متذللين..متواضعين لله.. مُخبتين.. مخلصين.. مؤمنين باللي ربنا أنزله.. \nوالإيمان مش مجرد كلام،\nلأ ...لازم يكون معاه عمل، يعني مينفعش واحد ييجي يقول أنا مؤمن بكلام ربنا ورسوله، فمالكوش دعوة باللي بعمله، الإيمان في القلب وربنا رب قلوب.. ويكون هو عمال يعمل معاصي ليل نهار ويجاهر بيها ومعتقد إن ربنا مش هيحاسبه بزعم إنه مؤمن وخلاص \nلإن الإيمان قول باللسان بنقوله، وتصديق بالقلب يعني بنبقى مصدقين بقلبنا كده إن ربنا هو الخالق وهو المستحق للعبادة،\nوعمل بالجوارح يعني جسمك بيتحرك بعمل الطاعات عشان يطبق الإيمان ده\nفلما نصلي يبقى احنا مؤمنين بإن ربنا هو الخالق المستحق للعبادة،\nلما ننفذ أوامر ربنا ونبعد عن الحاجات إللي نهى عنها، يبقى احنا مؤمنين بالله فعلا لأن احنا جمعنا بين الثلاثة:\nالكلام باللسان وتصديق القلب وعمل الجوارح\n◇وخدوا معلومة على الماشي كده\n الإيمان مش بيكون ثابت في القلب بدون زيادة أو نقصان، \nالإيمان بيزيد بالطاعات.. يعني كل ما نعمل طاعات خالصة لوجه الله الإيمان هيزيد في قلوبنا وهنحس بحلاوته،\nوالإيمان بيقل بسبب المعاصي .. يعني كل ما الإنسان بيعصي ربنا؛ إيمانه هيقل وقلبه بيضلم ويحس بهم وغم ونكد\n فنقدر نختصر السبب إللي خلى ربنا يستجيب لزكريا عليه السلام ويرزقه الولد إن كان هو وزوجته عندهم رصيد كبير جدا\nزي يونس عليه السلام لما كان في بطن الحوت وربنا أخرجه لأنه كان من المُسَبِّحين.. فاكرين\nوكمان أيوب عليه السلام لما صبر على البلاء وكان زي ما ربنا وصفه بإنه نِعْم العبد إنه أواب، وربنا استجاب له بأقل إشارة صدرت منه لما قال : \"أنِّي مَسَّني الضر وأنت الراحمين\"\n¤طيب هقولكم على قصة تانية يمكن ناس كتير متعرفهاش\nعارفين رسول الله ﷺ الحبيب ..أحب خلق الله إلى الله ..حصل خلاف بينه وبين زوجته حفصة بنت عمر بن الخطاب رضي الله عنهما، فطلقها\nشوفوا،\nكسر المرأة طلاقها زي ما رسول الله ﷺ قال،\nفما بالكم إذا كان إللي طلق هو رسول الله\n《السبب في الطلاق مفيش فيه حديث واضح لكن العلماء استنبطوا السبب من القصة إللي جت في القرآن: \"وإذ أسَرَّ النبي إلى بعض أزواجه حديثا فلما نبأت به\"..\nقالوا: إن الزوجة هنا حفصة، فلما أفشت سر النبي ﷺ ..رسول الله طلقها》\n☆احنا بنذكر لكم هنا  كلام العلماء عشان احنا عارفين فضول البعض الناس مننا، هنسيب الموضوع كله ونمسكوا في: طيب هو طلقها ليه يا تري\nالمهم.. فلما طلقها ، قعدت تبكي ودخل عليها خيلانها الإثنين بيواسوها وهي بتبكي وتقول:\nوالله ما طلقني من شِبع... يعني هو ماطلقنيش عشان زهق مني\nفوهمّ عالحال ده، لقوا الباب بيخبط! بيفتحوا الباب لقوه رسول الله ﷺ!\nفاستغربوا ..إيه إللي خلاك تيجي يا رسول الله مش إنت طلقتها.. !؟ فقال رسول الله ﷺ -وهي قاعدة وبتسمع:\nجاءني جبريل وقال إن الله جل جلاله أرسلني من فوق العرش وقال: قل لمحمد راجع حفصة ..\nيعني رجَّع حفصة لعصمتك تاني\nطيب ليه يارب من فوق سبع سموات تنزّل وحي في قضية زي دي وتقول لرسول الله راجع حفصة\nهل عشان عندها أجمل الفساتين...؟ ولّا عشان ماشية على أحدث خطوط الموضة...؟ ولّا عشان جمالها وحسبها ونسبها؟ ولا عشان إيه..؟ \nفيأتي الجواب: راجع حفصة فإنها ((صوّامة قوامة))..\nشوفتوا الرصيد\nيعني من الأسباب الرئيسية لاستجابة الدعاء ورفع البلاء إن الإنسان يكون له رصيد عند ربنا وقت الرخاء\nوانتم طبعا عارفين الحديث إللي بيقول: \"تعرّف إلى الله في الرخاء يعرفك في الشدة\"\nوالحديث التاني \"من سرّه أن يستجيب الله له عند الشدائد والكرب فليُكثر الدعاء في الرّخاء\"..\nيبقى احنا عندنا ثلاثة أسباب: \nالمسارعة في الخيرات// والدعاء رغبا ورهبا//والخشوع لله.\nلو بتعملوا الثلاثة دول : أبشروا \nطيب لو مش بتعملوهم لسه \nعاااادي ..نبدأ من دلوقتي.. لسه في فرصة ما دمنا على قيد الحياة .. والعبرة بالخواتيم .. \nوأَحسِن فيما بقي يُغفر لك ما مضى \nالمطلوب مننا إننا نبدأ وناخد خطوات للتغيير ..مش مطلوب مننا إننا نوصل للكمال\nخلينا ماشيين في طريق المسارعة في الخيرات حتى لو بنمشي خطوة ونقع التانية..\nهو الطفل الصغير مش أول ما بيبدأ المشي بيمشي خطوة ويقع التانية وبعدين يقوم ويفضل كده لحاااد ما تلاقيه بقى بيجري\nأهم حاجة إننا نبدأ مادام عرفنا الطريق\nلأن ربنا هيحاسبنا على مجهودنا مش هيحاسبنا على النتيجة\nأيوة احنا ممكن نسعى للكمال ونجاهد نفسنا إننا نقدم لربنا أفضل حاجة عندنا ،\nوده على فكرة من الحاجات إللي بتخلي همتنا عالية ومنرجعش لورا تاني ..لاااكن ميكنش الكمال غاية\n \nعشان ممكن يجيلنا إحباط\nفزكريا عليه السلام، لما الملائكة بشرته بالولد وهو قائم بيصلي قال :\nإزاي يكون عندي ولد وامرأتي عاقر وعمري خلاص داخل عالمائة سنة\n\"قَالَ رَبِّ أَنَّىَ يَكُونُ لِي غُلامٌ وَقَدْ بَلَغَنِيَ الْكِبَرُ وَامْرَأَتِي عَاقِرٌ\"\n☆هو مش لما دعا كان عارف الكلام ده كله يعني\n أيوة كان عارف.. بس سؤاله هنا سؤال تعجب مش سؤال استفهام،\nزي مثلا لما حد ييجي يقولك انت كسبت معانا رحلة عمرة..وتكون انت دعيت ليل نهار قبل إعلان النتيجة إنك تكسب فعلا.. فلما كسبت، أول حاجة بتيجي في بالك إيه..؟ مش بتقول لنفسك: إيه ده إزاي! معقول\nفرد المَلَك على زكريا: \n\"قَالَ كَذَلِكَ قَالَ رَبُّكَ هُوَ عَلَيَّ هَيِّنٌ وَقَدْ خَلَقْتُكَ مِن قَبْلُ وَلَمْ تَكُ شَيْئًا\".. \nيعني ربنا لما بيريد شيئ بيتحقق لإن بيده الأمر كله والأسباب كلها، بيهيأ الأسباب، \nولو مفيش أسباب؟ يقول للشيء كن فيكون...\nثم انت مستغرب ليه يا زكريا؟ ما ربنا خلقك انت وكل الناس من العدم\nفمش صعب عليه إطلاقا يخلق بشر من بشر تاني حتى لو عجوز عقيم..\nفزكريا عليه السلام من فرحته عايز يبقى في علامة ظاهرة كده إن الحمل حصل فعلا، \nفربنا أوحى له إن العلامة بتاعتك إنك مش هتقدر تكلم الناس ثلاثة أيام إلا بالإشارة..\nلما تكون لوحدك تتكلم عادي لكن لما تكون مع الناس مش هتقدر تتكلم إلا بالإشارة..\nيعني ده مش هيكون  بسبب إنك مريض، لأ، انت صحيح ومعافى تماما\n\"قَالَ رَبِّ اجْعَل لِّيَ آيَةً قَالَ آيَتُكَ أَلاَّ تُكَلِّمَ النَّاسَ ثَلاثَةَ أَيَّامٍ إِلاَّ رَمْزًا \"\nفلما خرج زكريا عليه السلام من المحراب عشان يمارس حياته ويدعو قومه ويذكّرهم بالله، مبقاش عارف يتكلم فعلا.. \nطب هل سكت وقال خلاص أنا مرفوع عني القدرة على الكلام حاليا فمش هدعو الناس لحد ما يرجع لي صوتي\n \nلأ،\nاستخدم معاهم لغة الإشارة عشان يذكرهم بالله\n\"فَخَرَجَ عَلَى قَوْمِهِ مِنَ الْمِحْرَابِ فَأَوْحَى إِلَيْهِمْ أَن سَبِّحُوا بُكْرَةً وَعَشِيًّا\"\n فأوحى إليهم يعني أشار إليهم من غير كلام..\n☆وده يعلمنا إننا نبلغ دين ربنا مهما كانت قدراتنا محدودة أو فيها عجز،\nندعو بالمتاح، وربنا بيحاسب على الوسع والطاقة..\nالنبي ﷺ قال: \"بلغوا عني ولو آية\".. \nمجرد آية تنشرها عندك في الفيس أو الواتس أو تعلقها في الأسانسير أو على باب بيتك كل اللي يزوركم يقرأها،\nأو على بطاقة وتوزعها على المحلات حد يشوفها فيتذكر ربنا ويتوب أو تأثر فيه فتزود إيمانه في لحظة يأس وحزن، ويبقى ده في ميزان حسناتك تندهش منه يوم القيامة من حيث لم تحتسب.. \nزي ما الإمام الشافعي قال: سيروا إلى الله عُرجا ومكاسير.. \nيعني مش لازم تكون عالم عشان تقول لأخوك أو صاحبك: عارف؟ ..من قال سبحان الله وبحمده ربنا بيغرس له نخلة في الجنة..\nمش لازم تكوني فقيهة عشان تقولي لأصحابك ولا أهلك: عارفين..؟ من قال أستغفر الله العظيم الذي لا إله إلا هو الحي القيوم وأتوب إيه ثلاثة مرات ربنا يغفر له ذنوبه كلها\n وهكذا... ما تتحججش بالعجز والفقر والضعف والمرض، اشتغل بالموجود، وربنا كريم، يضاعف لمن يشاء،\nالدعوة إلى الله مش مجرد حلال وحرام ونقول الدليل..\nرسول الله ﷺ قعد ١٣ سنة في مكة بيدعوا الناس لعبادة الله ويرغبهم في الجنة ويخوفهم من النار ويرغبهم في الأخلاق الحميدة،\nمعندكش علم بأصول الفقه ..بس على الأقل تقدر تقول للناس إن من قرأ آية الكرسي بعد كل صلاة مش هيمنعه من دخول الجنة إلا الموت...\nادخل على جوجل وابحث عن الأعمال البسيطة 《الصحيحة》 إللي ثوابها كبير وانشرها بين الناس..ويبقى انت كده دعيت إلى الله ...ودي أشرف شغلانة ممكن الإنسان يشتغلها \nوخليك فاكر إن أي حد هيعمل باللي انت قلته ونشرته فهو في ميزان حسناتك..تبقى في القبر وعداد حسناتك شغال...فمحدش يفوت الفرصة \nحملت زوجة زكريا عليه السلام بالنبي يحيى.. وبعد ثلاثة أشهر من حملها حصل حادث هو الأول والوحيد من نوعه على الأرض، هيعمل قلق وضجة شديدة جدا بين الناس \nإيه إللي هيحصل؟\nده إللي هنعرفه الجزء الجاي إن شاء الله"}]);
